    ('eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Quiz — Steinbeck, 1937 — le rêve d’une ferme, en Californie', 'Français', '1re', 'Des Souris et des Hommes, John Steinbeck', '07720f2d-c099-57b5-94a5-6d4611b6cfeb'::uuid),
    ('99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Quiz — Le Clézio, 1980 — deux exils, un même sable', 'Français', '1re', 'Désert, Jean-Marie Gustave Le Clézio', '21f5c12c-6ce6-5279-84f7-76d5f6efa342'::uuid),
    ('4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'Quiz — Voltaire, 1764 — la philosophie en articles portatifs', 'Français', '1re', 'Dictionnaire philosophique, Voltaire', '8183c18c-88e3-51c8-bc62-bb9355fb8496'::uuid),
    ('abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Quiz — La Boétie, vers 1548 — cessez d’obéir, et tout tombe', 'Français', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', '5b768c5e-7af1-5545-996b-092dc37a85ed'::uuid),
    ('b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Quiz — Molière, 1665 — le grand seigneur méchant homme', 'Français', '1re', 'Dom Juan, Molière', 'd72eb668-c828-5ef3-81e9-e369d9656eb1'::uuid),
    ('deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Quiz — Cervantes, 1605 et 1615 — le premier roman moderne', 'Français', '1re', 'Don Quichotte, Miguel de Cervantes', '067dc3ae-6246-5c53-8c52-05882a450620'::uuid),
    ('70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Quiz — Proust, 1913 — la madeleine et les deux côtés', 'Français', '1re', 'Du côté de chez Swann, Marcel Proust', '72e430f8-06ea-58a2-8121-697d08c60dee'::uuid),
    ('d8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Quiz — Giraudoux, 1937 — la vérité, même si la ville brûle', 'Français', '1re', 'Électre, Jean Giraudoux', '74b2155a-ceca-5857-882f-d24dc9c6b9ab'::uuid),
    ('5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Quiz — Beckett, 1953 — deux actes où rien n’arrive, deux fois', 'Français', '1re', 'En attendant Godot, Samuel Beckett', 'c2ccaf11-cde8-5df0-8fa3-adb5bf232fa8'::uuid),
    ('8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'Quiz — Diderot et d’Alembert, 1751-1772 — l’arbre des savoirs', 'Français', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'ce7912c8-dd37-567d-95a4-977d5ce2d7aa'::uuid),
    ('827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Quiz — Virgile, Ier siècle av. J.-C. — l’épopée fondatrice de Rome', 'Français', '1re', 'Énéide, Virgile', 'cf4fb497-1101-5565-80cd-918ca2e24ed7'::uuid),
    ('63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Quiz — Fontenelle, 1686 — la science expliquée à une marquise', 'Français', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'd5b38355-9bb0-5ab1-8fc3-ec9225a650be'::uuid),
    ('b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Quiz — Montaigne, 1580-1592 — « je suis moi-même la matière de mon livre »', 'Français', '1re', 'Essais, Michel de Montaigne', 'e0e21965-16d0-50ef-a566-ad6a15cab036'::uuid),
    ('8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Quiz — Senghor, 1956 — la négritude en poèmes', 'Français', '1re', 'Éthiopiques, Léopold Sédar Senghor', '00f543d7-5bc2-5612-a940-dec930fd2020'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('28c12d84-ab6f-506e-a821-5fc9c598ddf3'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'Qu’achète Serge au début de la pièce ?', 'mcq', '["Un tableau entièrement blanc, très cher","Une sculpture antique","Une maison de campagne","Un tableau de maître ancien"]'::jsonb, 0, 'Le prix, exorbitant, est l’étincelle de la dispute.', 1),
    ('754d2903-741b-5df3-bf77-1f29e8787f33'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'Combien de personnages la pièce compte-t-elle ?', 'mcq', '["Trois","Deux","Quatre","Cinq"]'::jsonb, 0, 'Serge, Marc et Yvan, qui s’adressent aussi directement au public.', 2),
    ('c3fb865c-db3d-5361-8185-4ae9d9caf5b3'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'Quel est le vrai sujet de la dispute ?', 'mcq', '["L’amitié et l’ascendant que chacun exerce sur l’autre","La valeur marchande de l’art","Un héritage familial","Une rivalité amoureuse"]'::jsonb, 0, 'Le tableau n’est que le déclencheur.', 3),
    ('3ea5a8d7-c20c-5c0c-8a5f-3a0a38dc62ff'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'Quel personnage prononce une longue tirade sur son mariage ?', 'mcq', '["Yvan","Marc","Serge","Le peintre"]'::jsonb, 0, 'Le morceau de bravoure comique de la pièce.', 4),
    ('f8f42e98-b0c3-528e-b2c4-37dc7cb7c9dd'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'À quel genre la pièce appartient-elle ?', 'mcq', '["La comédie grinçante contemporaine","La tragédie","Le drame romantique","La farce médiévale"]'::jsonb, 0, 'Dialogue rapide, scènes brèves, décor unique.', 5),
    ('82fbb1b2-1c9b-5aad-ba1d-3dd7737bd653'::uuid, 'ca06e49c-97c4-5e5a-ae71-31958c5d740e'::uuid, 'La pièce se termine par la destruction totale de l’amitié.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le lien survit, abîmé et réinventé : c’est ce qui rend le dénouement ambigu.', 6),
    ('91dcad30-0b50-5e68-a41d-8e6e7e0d6aaf'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'Qui est le « je » du poème ?', 'mcq', '["Un bateau qui descend le fleuve puis se perd en mer","Un marin","Le poète lui-même","Un enfant sur la berge"]'::jsonb, 0, 'La métaphore file sur tout le poème.', 1),
    ('9eda3557-28e4-5353-9798-f111ec1f856f'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'Quel âge a Rimbaud lorsqu’il écrit Le Bateau ivre ?', 'mcq', '["Seize ans","Vingt ans","Vingt-cinq ans","Dix-huit ans"]'::jsonb, 0, 'Et il n’a alors jamais vu la mer.', 2),
    ('52c72e4c-199f-5df0-8483-27f71c287ed6'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'Quelle est la forme du poème ?', 'mcq', '["Vingt-cinq quatrains d’alexandrins","Un sonnet","Un poème en prose","Des vers libres"]'::jsonb, 0, 'La régularité formelle contraste avec le déferlement des images.', 3),
    ('ca21db7e-97d4-56d7-b9be-3b5d294f6da7'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'Comment le poème se termine-t-il ?', 'mcq', '["Par le désir d’une flaque d’eau d’Europe et d’un bateau d’enfant","Par un naufrage total","Par le retour au port","Par la mort du marin"]'::jsonb, 0, 'Après l’ivresse vient la fatigue : le retour rêvé est minuscule.', 4),
    ('9f340aef-b2a6-58d3-822a-12d653a5ef94'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'À qui Rimbaud envoie-t-il le poème ?', 'mcq', '["À Verlaine","À Hugo","À Baudelaire","À Mallarmé"]'::jsonb, 0, 'Verlaine l’invite alors à Paris.', 5),
    ('315bef4b-d416-51dc-89a0-b8df7744d1a4'::uuid, 'a2e248c7-b417-5ed3-85df-5d14f76fccaa'::uuid, 'L’exotisme du poème vient des voyages réels de Rimbaud.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est entièrement livresque, tiré de ses lectures d’enfance.', 6),
    ('798ac7b4-58fa-5cac-8195-c85cda4e5a2f'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Quelles sont les trois femmes du récit ?', 'mcq', '["Sylvie, Adrienne et Aurélie","Sylvie, Aurélie et Jenny","Adrienne, Émilie et Sylvie","Aurélie, Delphine et Sylvie"]'::jsonb, 0, 'Le réel, l’idéal et l’illusion : le narrateur les confond.', 1),
    ('71d12633-9bd4-5f1d-9d98-56e40411f934'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Dans quelle région se déroule le récit ?', 'mcq', '["Le Valois","La Bretagne","La Provence","Le Berry"]'::jsonb, 0, 'Le pays d’enfance de Nerval, dont il fait un espace de mémoire.', 2),
    ('dd0165da-5620-5757-b5cc-e5f717f0ad56'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Qui est Adrienne ?', 'mcq', '["Une jeune fille aperçue une fois, devenue religieuse et morte","Une paysanne du village","Une actrice parisienne","La sœur de Sylvie"]'::jsonb, 0, 'Elle est l’idéal inaccessible, revu partout ensuite.', 3),
    ('a98ce346-3018-5dc2-a386-0343fbd7e786'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Qu’est-ce qui déclenche le départ du narrateur ?', 'mcq', '["Un entrefilet de journal annonçant une fête au pays","Une lettre de Sylvie","La mort d’un ami","Un rêve"]'::jsonb, 0, 'Le hasard d’une lecture ouvre la porte du souvenir.', 4),
    ('13ed8382-8a95-5ec7-9f46-d8f1cee8bd83'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Quelle particularité présente la narration ?', 'mcq', '["Les époques se superposent sans transition marquée","Le récit est strictement chronologique","Il n’y a pas de narrateur","Le récit est écrit en vers"]'::jsonb, 0, 'C’est ce qui a fasciné Proust.', 5),
    ('4b4ce6fb-33aa-5f2a-b9e4-7424b3b064f6'::uuid, 'd7145fa1-8f3f-52d7-b085-bb1eb65cc695'::uuid, 'Le narrateur finit par épouser Sylvie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle épouse un autre : le récit est celui d’une occasion manquée.', 6),
    ('c2aedc31-8acd-566a-aab5-beeda6951759'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Qui est Félicité ?', 'mcq', '["Une servante qui sert la même famille pendant un demi-siècle","Une bourgeoise de Rouen","Une religieuse","Une paysanne propriétaire"]'::jsonb, 0, 'Sa vie est une suite de pertes successives.', 1),
    ('bbd3b99e-cd31-5229-9a27-c732e777eb6f'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Qui est Loulou ?', 'mcq', '["Le perroquet de Félicité, qu’elle fait empailler","Son neveu","Le fils de Madame Aubain","Son chien"]'::jsonb, 0, 'Il devient l’ultime objet de son amour, puis une image du Saint-Esprit.', 2),
    ('376805fb-1644-5ce5-af14-f26f848e8b5e'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Comment le conte se termine-t-il ?', 'mcq', '["Félicité meurt en croyant voir un perroquet gigantesque dans les cieux","Félicité hérite de la maison","Félicité retrouve son fiancé","Félicité quitte Pont-l’Évêque"]'::jsonb, 0, 'La confusion est prise au sérieux, sans ironie.', 3),
    ('b7f0e778-88d3-53a4-baa4-6a691a3435d7'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Pour qui Flaubert écrit-il ce conte ?', 'mcq', '["Pour George Sand, qui lui reprochait d’être sans cœur","Pour sa nièce Caroline","Pour Maupassant","Pour Louise Colet"]'::jsonb, 0, 'Il voulait prouver qu’il pouvait écrire la bonté sans ironie.', 4),
    ('1ad6b26c-cf52-5ea7-ae0f-eaf98a274902'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Quelle est la tonalité du style dans ce conte ?', 'mcq', '["Une sobriété absolue, sans pathos ni ironie","Un lyrisme exalté","Une satire mordante","Un comique de situation"]'::jsonb, 0, 'C’est ce qui rend la dernière page bouleversante.', 5),
    ('c63f6817-86d9-527f-982c-b1a8a98d74de'::uuid, 'db95c87a-5f30-5c2a-aba9-2f9cd1df1c2f'::uuid, 'Félicité sait lire et écrire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est illettrée : son amour ne passe jamais par les mots.', 6),
    ('c7bfa34b-e3ae-598e-8ae1-af29ae9ea661'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Où travaille Winston Smith ?', 'mcq', '["Au ministère de la Vérité, où il réécrit les archives","Au ministère de l’Amour","À la Police de la Pensée","Dans une usine d’armement"]'::jsonb, 0, 'Son métier consiste à faire dire au passé ce que le Parti veut.', 1),
    ('9f5ba781-26a2-57e0-9218-05d9623468ef'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Qu’est-ce que le novlangue ?', 'mcq', '["Une langue appauvrie qui rend la révolte impensable","Un code secret des résistants","La langue des étrangers","Un dialecte régional interdit"]'::jsonb, 0, 'Réduire le vocabulaire, c’est réduire ce qui peut être pensé.', 2),
    ('cc2f8072-9dbd-57ed-98d7-95841858c246'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Qui est O’Brien ?', 'mcq', '["Un agent de la Police de la Pensée, faux allié de Winston","Le chef de la résistance","Le frère de Julia","Un télécran"]'::jsonb, 0, 'C’est lui qui torturera Winston dans la chambre 101.', 3),
    ('0f800b4f-5878-5307-aaf0-0e31066379dd'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Winston, brisé, finit par aimer Big Brother","Winston s’évade","Winston renverse le Parti","Winston meurt en résistant"]'::jsonb, 0, 'La défaite est totale : elle est intérieure.', 4),
    ('bd623b08-a2f2-554f-84c6-05bd5ba5c05f'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Qu’est-ce que la double-pensée ?', 'mcq', '["La capacité de croire simultanément deux choses contradictoires","La censure des livres","Le langage codé des amants","La surveillance par deux écrans"]'::jsonb, 0, 'Elle rend la contradiction indolore, donc le mensonge durable.', 5),
    ('dd36343d-ab0a-53db-8d12-ae9430235e1f'::uuid, 'd8f5f0ef-c9ce-57ff-b20a-d388286b2caa'::uuid, 'Le roman a été écrit avant la Seconde Guerre mondiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il paraît en 1949, marqué par le stalinisme et par la guerre d’Espagne.', 6),
    ('69c2e514-02e0-5d2a-89ba-02d5f9599cc9'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Quel prix ce volume a-t-il obtenu ?', 'mcq', '["Le prix Goncourt 1919","Le prix Renaudot","Le prix Femina","Aucun prix"]'::jsonb, 0, 'La récompense fit sortir Proust de la confidentialité.', 1),
    ('9dd9dcec-b3f1-54de-87ed-290c0dc55278'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Où se déroule la seconde partie du livre ?', 'mcq', '["À Balbec, station balnéaire normande","À Combray","À Venise","À Paris uniquement"]'::jsonb, 0, 'Le narrateur y séjourne avec sa grand-mère.', 2),
    ('ea8c67dc-d7af-5e95-8ae5-490f6f6c4d8f'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Quel personnage le narrateur rencontre-t-il dans la « petite bande » ?', 'mcq', '["Albertine","Odette","Oriane de Guermantes","Gilberte"]'::jsonb, 0, 'Elle deviendra centrale dans les volumes suivants.', 3),
    ('481990ba-f238-5305-a1e4-7120da983401'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Quel peintre apprend au narrateur à regarder ?', 'mcq', '["Elstir","Vinteuil","Bergotte","Swann"]'::jsonb, 0, 'Vinteuil est le musicien, Bergotte l’écrivain : chaque art a son maître dans la Recherche.', 4),
    ('8a0398b3-d804-5000-a825-da26979c09d1'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Quel sentiment revient face aux choses longtemps imaginées ?', 'mcq', '["La déception","L’exaltation","L’indifférence","La peur"]'::jsonb, 0, 'L’église de Balbec ou la Berma en scène ne ressemblent pas au rêve.', 5),
    ('86f2ee26-9ae5-5a19-b23e-0b5e891af962'::uuid, 'df161a13-d98f-55ea-8932-7b2b2b2d3bcb'::uuid, 'Le volume raconte une intrigue riche en péripéties.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’apprentissage d’un regard : le mouvement de la conscience y remplace l’action.', 6),
    ('bd7b440f-b782-5481-8c2c-5f453f9e953c'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'Pourquoi Adolphe séduit-il Ellénore ?', 'mcq', '["Par vanité, pour prouver qu’il en est capable","Par amour immédiat et sincère","Pour obtenir une fortune","Pour obéir à son père"]'::jsonb, 0, 'L’amour naît de l’orgueil, et meurt dès qu’il est comblé.', 1),
    ('77adefe8-6692-5653-b529-7e4d1fb8a374'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'Pourquoi Adolphe reste-t-il auprès d’Ellénore alors qu’il ne l’aime plus ?', 'mcq', '["Par pitié, faiblesse et peur de la faire souffrir","Parce qu’il l’aime encore","Parce qu’il est retenu par sa famille","Par intérêt financier"]'::jsonb, 0, 'Le roman démonte cette lâcheté sentimentale, qui fait plus de mal que la rupture.', 2),
    ('0d2b0d74-6e79-5afe-9459-9246f499a886'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Ellénore meurt après avoir lu une lettre d’Adolphe","Ils se marient","Adolphe part à l’étranger sans nouvelle","Ellénore retourne auprès du comte"]'::jsonb, 0, 'La lettre où il promettait de la quitter la tue.', 3),
    ('8accc98e-bb7c-5aa8-8f70-80da06b994de'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'Quel dispositif encadre le récit ?', 'mcq', '["Un « éditeur » qui prétend avoir trouvé le manuscrit","Un dialogue avec un ami","Une préface de l’auteur signée","Aucun"]'::jsonb, 0, 'Le procédé donne au récit un air de document authentique.', 4),
    ('3b8e5390-a994-5dde-8f20-bd6cc0da9483'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'À quel genre le livre appartient-il ?', 'mcq', '["Le récit-confession à la première personne","Le roman épistolaire","Le roman-fleuve","Le conte philosophique"]'::jsonb, 0, 'Très bref, il tient de l’analyse plus que de l’aventure.', 5),
    ('366c6201-67d4-54d2-b758-60882e75188c'::uuid, '2dde6891-4d91-5045-930b-3dc547aca1f2'::uuid, 'Le style d’Adolphe est lyrique et abondant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est d’une sécheresse classique, malgré un sujet romantique.', 6),
    ('0bd400b8-3bc5-5351-b355-636c67e7c4ac'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'Quelle décision Apollinaire prend-il sur les épreuves ?', 'mcq', '["Supprimer toute la ponctuation","Renoncer aux rimes","Classer les poèmes par date","Publier sous pseudonyme"]'::jsonb, 0, 'Le rythme et la coupe des vers doivent suffire.', 1),
    ('fed1f9fd-113f-55bf-bb80-465d5c90fbbf'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'Quel poème ouvre le recueil ?', 'mcq', '["Zone","Le Pont Mirabeau","Vendémiaire","Nuit rhénane"]'::jsonb, 0, 'Il a pourtant été écrit en dernier.', 2),
    ('700e1b3e-18fd-5d68-b141-cdfaefcd7aec'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'Que raconte « Le Pont Mirabeau » ?', 'mcq', '["L’amour qui s’en va comme l’eau du fleuve","Un accident de la Seine","La construction d’un pont","Une promenade joyeuse"]'::jsonb, 0, 'Le refrain installe la permanence du poète face au passage du temps.', 3),
    ('ad583cb6-0270-5d2e-8967-8181be6386cc'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'En quelle année le recueil paraît-il ?', 'mcq', '["1913","1900","1920","1898"]'::jsonb, 0, 'À la veille de la guerre où Apollinaire sera blessé.', 4),
    ('f599d59f-5240-5bc4-ab0b-42e8b86a5ba5'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'Quels éléments modernes entrent dans « Zone » ?', 'mcq', '["Les affiches, la tour Eiffel, l’aviation","Les héros mythologiques seuls","La campagne normande","Les batailles napoléoniennes"]'::jsonb, 0, 'Ils voisinent avec la religion d’enfance et les souvenirs de voyage.', 5),
    ('693988f5-d1cd-5980-8c99-f48622bb0ebf'::uuid, '0961180f-2de7-5a53-b5b4-2488caed4598'::uuid, 'La modernité d’Apollinaire consiste à rejeter toute forme traditionnelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un alliage : les chansons régulières côtoient les audaces.', 6),
    ('ac8af35d-2ab9-5609-a573-b18940d6d6ed'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Quelle est la chaîne amoureuse de la pièce ?', 'mcq', '["Oreste aime Hermione, qui aime Pyrrhus, qui aime Andromaque, fidèle à Hector","Pyrrhus aime Hermione, qui aime Oreste","Andromaque aime Pyrrhus","Oreste aime Andromaque"]'::jsonb, 0, 'Chacun exige d’être aimé de qui ne le peut pas.', 1),
    ('1aa31eb7-18af-5072-8ad1-49cde1c14ba4'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Avec quoi Pyrrhus fait-il chanter Andromaque ?', 'mcq', '["Avec la vie de son fils Astyanax","Avec la liberté des Troyennes","Avec le tombeau d’Hector","Avec la paix entre les Grecs"]'::jsonb, 0, 'Le chantage est le moteur de toute l’intrigue.', 2),
    ('368063b8-15fd-5261-acb2-10dd27b631e0'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Que décide Andromaque avant la cérémonie ?', 'mcq', '["Épouser Pyrrhus puis se tuer","Fuir avec Oreste","Livrer son fils","Renoncer à sauver Astyanax"]'::jsonb, 0, 'Sauver l’enfant sans trahir Hector : c’est sa seule issue.', 3),
    ('8fe22f9f-cff3-5883-89bb-00255041b89e'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Qui ordonne le meurtre de Pyrrhus ?', 'mcq', '["Hermione","Andromaque","Oreste de lui-même","Les ambassadeurs grecs"]'::jsonb, 0, 'Elle maudira ensuite Oreste d’avoir obéi.', 4),
    ('590f3aff-3df8-557a-95ad-6e6fc07a42ea'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Comment finit Oreste ?', 'mcq', '["Il devient fou","Il épouse Hermione","Il retourne en Grèce en triomphe","Il est tué par Pyrrhus"]'::jsonb, 0, 'La scène de folie clôt la pièce.', 5),
    ('b871a905-1673-54ef-9e17-98d4da6950c7'::uuid, '5ed34ae4-6892-53d1-b551-9a2b7c1fc33b'::uuid, 'Andromaque cède à la passion au cours de la pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste fidèle à Hector : c’est ce qui la rend inébranlable et tragique.', 6),
    ('e353ea9b-9664-521e-9c3c-ce01e2dbfc5c'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'En quelle année la pièce est-elle créée ?', 'mcq', '["1944, sous l’Occupation","1936","1950","1922"]'::jsonb, 0, 'Les deux camps y ont lu leur propre message.', 1),
    ('1ec33369-4770-509a-a1dc-8b97ac3b2aa7'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'Comment Créon est-il représenté chez Anouilh ?', 'mcq', '["Comme un homme fatigué qui argumente et tente de sauver Antigone","Comme un tyran sanguinaire","Comme un vieillard sénile","Comme un guerrier héroïque"]'::jsonb, 0, 'C’est ce qui rend le refus d’Antigone plus radical encore.', 2),
    ('ed14a3e7-d1cb-5fbd-829c-5686c3403523'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'Que révèle Créon à Antigone sur ses frères ?', 'mcq', '["Qu’ils étaient tous deux indignes et qu’on ignore quel corps a été enterré","Qu’ils sont vivants","Qu’ils ont été trahis par Ismène","Qu’ils ont demandé pardon"]'::jsonb, 0, 'Le geste d’Antigone perd sa justification, et elle refuse quand même.', 3),
    ('daf31643-f4a5-5167-90df-37ba37886cf4'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'Quel est le rôle du prologue ?', 'mcq', '["Présenter les personnages et annoncer la fin","Résumer la pièce de Sophocle","Introduire un narrateur comique","Justifier les anachronismes"]'::jsonb, 0, 'La tragédie est une mécanique qui « se déroule toute seule ».', 4),
    ('19601162-6775-594f-8703-6cb4fc77f95e'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'Qui meurt à la fin de la pièce ?', 'mcq', '["Antigone, Hémon et Eurydice","Antigone seule","Créon et Antigone","Personne"]'::jsonb, 0, 'Créon, lui, reste et retourne au conseil : c’est sa punition.', 5),
    ('1875d42c-cda2-5a93-8151-3ce8e31b73db'::uuid, '178d9d89-cf49-5c70-9a8c-927cf3e320d4'::uuid, 'Le langage de la pièce est celui de la tragédie classique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est familier, avec des anachronismes assumés — cigarettes, gardes qui parlent de leur solde.', 6),
    ('fc317004-e426-55e9-8c42-ebbe8ed33ce5'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Pourquoi Antigone brave-t-elle l’interdit de Créon ?', 'mcq', '["Pour donner une sépulture à son frère Polynice, au nom des lois divines","Pour prendre le pouvoir","Pour venger son père Œdipe","Pour sauver Ismène"]'::jsonb, 0, 'Elle invoque les lois non écrites, supérieures aux décrets humains.', 1),
    ('b1700fe2-b781-5c62-bcfe-f5babdee0534'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Qui est Créon dans la pièce de Sophocle ?', 'mcq', '["Le roi de Thèbes, oncle d’Antigone","Le frère d’Antigone","Le devin de la cité","Le fiancé d’Antigone"]'::jsonb, 0, 'Hémon, son fils, est le fiancé d’Antigone.', 2),
    ('4c8069d0-f1e0-59c9-af97-d2a647c6bf57'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Comment Antigone meurt-elle ?', 'mcq', '["Elle se pend dans le tombeau où elle est emmurée","Elle est décapitée","Elle est lapidée","Elle meurt de faim en exil"]'::jsonb, 0, 'Hémon puis Eurydice se donnent la mort ensuite.', 3),
    ('3416d162-793c-5bd3-a9c7-a01e60555009'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Quel personnage avertit Créon trop tard ?', 'mcq', '["Le devin Tirésias","Ismène","Le chœur","Hémon"]'::jsonb, 0, 'La démesure de Créon l’a empêché d’écouter à temps.', 4),
    ('d7b8e8ce-b561-55db-9ecf-099c170df1f0'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Quel conflit la pièce met-elle en scène ?', 'mcq', '["La loi divine et familiale contre la raison d’État","L’amour contre le devoir militaire","La jeunesse contre la vieillesse seulement","La richesse contre la pauvreté"]'::jsonb, 0, 'Aucun des deux camps n’a entièrement tort : c’est la force du texte.', 5),
    ('97da3e70-c968-5b53-85b7-582add374ea6'::uuid, '36ee316a-5f5a-524d-ac25-e0c957b282ce'::uuid, 'Ismène accepte dès le début d’aider Antigone.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle refuse d’abord, puis veut partager la faute — et Antigone l’écarte.', 6),
    ('211ca308-0343-51da-b037-c8280823a4b2'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Quel est le premier roman publié de Stendhal ?', 'mcq', '["Armance","Le Rouge et le Noir","La Chartreuse de Parme","Lucien Leuwen"]'::jsonb, 0, 'Il paraît en 1827, avant Le Rouge et le Noir.', 1),
    ('a5a110a7-e4d8-5b10-9f35-43efe8c56b7d'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Qu’est-ce qui empêche Octave d’épouser Armance ?', 'mcq', '["Un secret intime que le roman ne nomme jamais","Une différence de religion","Un serment fait à son père","Une dette de jeu"]'::jsonb, 0, 'Stendhal évoque dans ses lettres l’impuissance du héros.', 2),
    ('30b74b80-d9ec-5cab-b0a1-3b3064b21ff3'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Pourquoi Armance cache-t-elle son amour ?', 'mcq', '["Pour ne pas paraître intéressée par la fortune d’Octave","Parce qu’elle en aime un autre","Parce qu’elle veut entrer au couvent","Parce que sa famille l’interdit"]'::jsonb, 0, 'La loi d’indemnisation des émigrés vient d’enrichir Octave.', 3),
    ('a769d686-cde2-5103-9734-1a053bbd27a8'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Octave s’empoisonne en mer, en route vers la Grèce","Le couple s’installe à Paris","Armance meurt de chagrin","Octave épouse une autre femme"]'::jsonb, 0, 'Le mariage n’a rien résolu du secret.', 4),
    ('9d83026b-2904-5e46-b560-a8e62320d2a4'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Quel milieu le roman peint-il ?', 'mcq', '["Le salon aristocratique de la Restauration","La bourgeoisie industrielle","Le monde paysan","Les milieux militaires"]'::jsonb, 0, 'Le sous-titre l’annonce : « Quelques scènes d’un salon de Paris en 1827 ».', 5),
    ('672dd740-ea99-5b4d-9b56-7fcf548e1cbc'::uuid, '31852e80-3b23-581e-ab41-50b1bf164833'::uuid, 'Le roman nomme explicitement le secret d’Octave.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Tout y est allusif : c’est un roman du non-dit, ce qui a dérouté ses premiers lecteurs.', 6),
    ('984863b5-90e2-5532-a7b3-67ccf0c5706f'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Qui a écrit l’essentiel d’Artamène ?', 'mcq', '["Madeleine de Scudéry, sous le nom de son frère Georges","Georges de Scudéry seul","Madame de Lafayette","Honoré d’Urfé"]'::jsonb, 0, 'La signature masculine était une convention de l’époque.', 1),
    ('083eedfa-adfd-5f0f-99d3-460fbd85970a'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Quelle est la particularité matérielle du roman ?', 'mcq', '["C’est le plus long roman de la littérature française, en dix volumes","Il est écrit en vers","Il tient en un seul volume","Il est resté inachevé"]'::jsonb, 0, 'Environ deux millions de mots.', 2),
    ('d954f78e-d588-5f87-9722-4d149b894300'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Quel cadre historique le roman utilise-t-il ?', 'mcq', '["L’Antiquité perse, autour du prince Cyrus","La Rome impériale","La Grèce classique","L’Égypte des pharaons"]'::jsonb, 0, 'Le héros se fait appeler Artamène.', 3),
    ('e48f1f8b-1925-579b-868f-4b1d48625cc9'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Qu’est-ce qui intéressait surtout les lecteurs du temps ?', 'mcq', '["Les conversations, les portraits et les questions galantes","Les batailles","Les descriptions de paysages","La morale religieuse"]'::jsonb, 0, 'La trame héroïque n’est qu’un cadre.', 4),
    ('a5ef4ce3-6737-5f54-96a2-007d73f1e2e1'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Qu’appelle-t-on un roman « à clé » ?', 'mcq', '["Un roman où les contemporains reconnaissent des personnes réelles sous des noms d’emprunt","Un roman policier","Un roman inachevé","Un roman publié anonymement"]'::jsonb, 0, 'C’était un jeu de salon très prisé.', 5),
    ('cb4d405a-31f6-53f5-8825-dd1234e58996'::uuid, 'fe5f0176-9988-5dd8-97f1-49cbce6ab5e1'::uuid, 'Le roman a connu un succès durable jusqu’au XIXe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Immense succès d’abord, il est raillé et oublié dès la fin du XVIIe siècle.', 6),
    ('efe22b23-0273-588b-8762-ae6d79f02a2b'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'Qui est Denise Baudu ?', 'mcq', '["Une orpheline devenue vendeuse au Bonheur des Dames","La femme d’Octave Mouret dès le début","La propriétaire du magasin","Une cliente fortunée"]'::jsonb, 0, 'Elle vient de Valognes avec ses deux frères à charge.', 1),
    ('f8260318-441d-56bb-b449-0da9a582ef5f'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'Qui dirige le grand magasin ?', 'mcq', '["Octave Mouret","Baudu","Bourras","Robineau"]'::jsonb, 0, 'Séducteur et génie du commerce, il finit par aimer Denise.', 2),
    ('5eacec00-12b8-56a0-bfba-d286146e4d38'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'Que provoque le développement du grand magasin ?', 'mcq', '["La ruine des petits commerçants du quartier","La hausse des salaires","La fermeture des usines","Le départ des clientes"]'::jsonb, 0, 'L’oncle Baudu en est la victime la plus visible.', 3),
    ('a56c9fac-5afa-5efb-8177-335f00f29c41'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'Quelles techniques commerciales le roman décrit-il ?', 'mcq', '["Étalages, soldes, publicité, vente par correspondance","Le troc et le crédit à la ferme","Les foires annuelles","La vente aux enchères"]'::jsonb, 0, 'Zola documente la naissance du commerce moderne.', 4),
    ('9f56c456-26fd-53b1-babe-45b056daca69'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'À quelle série le roman appartient-il ?', 'mcq', '["Les Rougon-Macquart","Les Trois Villes","Les Quatre Évangiles","La Comédie humaine"]'::jsonb, 0, 'C’est le onzième volume du cycle.', 5),
    ('946bca29-1b22-5e16-825b-702c73c0cd9a'::uuid, 'ca207de5-ce7f-5616-a37b-c6e28a622cf5'::uuid, 'Denise devient la maîtresse de Mouret.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle refuse et finit par l’épouser : c’est ce qui rend le roman singulier chez Zola.', 6),
    ('4bb0263a-3421-5c91-8c78-fae05a888816'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'Que proposent les d’Hubières aux deux familles paysannes ?', 'mcq', '["Adopter un de leurs enfants contre une rente","Employer les parents chez eux","Racheter leur ferme","Payer l’école des enfants"]'::jsonb, 0, 'Une famille refuse, l’autre accepte : toute la nouvelle est là.', 1),
    ('e6195d46-0542-5a78-a460-485924afcbf2'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'Quelle famille accepte de céder son enfant ?', 'mcq', '["Les Vallin","Les Tuvache","Les deux","Aucune"]'::jsonb, 0, 'Les Tuvache refusent avec indignation et se croient supérieurs.', 2),
    ('e56f8165-5e08-5c76-9567-63e839942e16'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'Que se passe-t-il vingt ans plus tard ?', 'mcq', '["Jean revient riche, et Charlot reproche à ses parents leur refus","Jean meurt en ville","Les deux familles se réconcilient","Les d’Hubières reviennent chercher un second enfant"]'::jsonb, 0, 'La chute retourne toute la morale du récit.', 3),
    ('86e9ae33-0b36-5ab7-8b1a-ad9d4c428972'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'Sur quelle construction repose la nouvelle ?', 'mcq', '["Une symétrie parfaite entre les deux familles","Un récit enchâssé","Un journal intime","Une succession de lettres"]'::jsonb, 0, 'La symétrie rend la comparaison finale implacable.', 4),
    ('e2b31937-7229-5e49-822c-0ff4d2b948e3'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'Quelle position Maupassant adopte-t-il ?', 'mcq', '["Il montre sans juger, et laisse la chute parler","Il condamne les Vallin","Il condamne les Tuvache","Il défend les d’Hubières"]'::jsonb, 0, 'Le geste moral produit du malheur, le geste scandaleux une réussite.', 5),
    ('54ab8227-de78-5e41-984e-1682703cd152'::uuid, 'a889f30f-fbe0-5073-baee-6f6f9c6d0f28'::uuid, 'La nouvelle appartient au mouvement réaliste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Milieu paysan, langage rendu, absence d’idéalisation : Maupassant est un réaliste doublé d’un naturaliste.', 6),
    ('4ec473d8-be56-5cce-b5e1-b8eea3f83c42'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Où se déroule la tragédie ?', 'mcq', '["Dans le sérail de Constantinople","À Rome","À Athènes","En Épire"]'::jsonb, 0, 'Un espace clos où la parole est surveillée.', 1),
    ('d24106e2-f259-586f-aa4b-168a47ba792b'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Quel marché Roxane propose-t-elle à Bajazet ?', 'mcq', '["L’épouser et régner, ou mourir","Fuir avec elle","Trahir Amurat en échange de sa liberté","Épouser Atalide"]'::jsonb, 0, 'Bajazet aime Atalide : il feindra, et cela le perdra.', 2),
    ('6a8b075f-97ab-58e9-9da6-07a9da428371'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Qui conseille à Bajazet de feindre l’amour pour Roxane ?', 'mcq', '["Atalide","Acomat","Amurat","Osmin"]'::jsonb, 0, 'Elle croit ainsi le sauver ; elle cause sa mort.', 3),
    ('7ab4e1b3-8bd3-5056-b3c1-0e039bf27049'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Qu’est-ce qui révèle la vérité à Roxane ?', 'mcq', '["Une lettre","Un aveu d’Acomat","Un espion du sultan","Un rêve"]'::jsonb, 0, 'La preuve écrite déclenche le dénouement.', 4),
    ('1823e071-8311-5253-b5ca-7a8a5538828e'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Quelle particularité cette tragédie présente-t-elle chez Racine ?', 'mcq', '["Elle est tirée d’une histoire contemporaine","Elle est écrite en prose","Elle finit bien","Elle n’a pas d’unité de lieu"]'::jsonb, 0, 'Racine invoque l’éloignement géographique comme substitut à l’éloignement dans le temps.', 5),
    ('6f8277af-cc58-5e90-b2df-a8f87fb42386'::uuid, '33c7d45f-a29d-5c42-850d-c43f521f7948'::uuid, 'Bajazet survit à la pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Roxane le fait exécuter ; elle est ensuite tuée, et Atalide se donne la mort.', 6),
    ('0f4bfd5f-60fe-5c6c-a911-dc102b192ca5'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Quel est le vrai nom de Bel-Ami ?', 'mcq', '["Georges Duroy","Charles Forestier","Norbert de Varenne","Jacques Rival"]'::jsonb, 0, 'Il deviendra « Du Roy de Cantel » à force d’ambition.', 1),
    ('67408706-cfad-5414-86be-dbe34a7fdcd4'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Comment Duroy entre-t-il dans le journalisme ?', 'mcq', '["Grâce à son ancien camarade Forestier","Par un concours","Par héritage","Par une école de journalisme"]'::jsonb, 0, 'Ses premiers articles sont écrits par Madeleine Forestier.', 2),
    ('f3620e2b-8c61-569f-8738-60ac1dc9dd99'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Que fait Duroy pour se débarrasser de Madeleine ?', 'mcq', '["Il la fait surprendre en adultère pour divorcer","Il l’abandonne sans explication","Il l’envoie en province","Il la ruine"]'::jsonb, 0, 'Le divorce lui permet d’épouser plus haut.', 3),
    ('6dde31c2-cddd-5ee6-a331-e94550b80353'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Par son mariage triomphal avec Suzanne Walter","Par sa ruine","Par un duel mortel","Par son départ pour l’Algérie"]'::jsonb, 0, 'L’arriviste n’est pas puni : c’est la force du roman.', 4),
    ('9f095aab-7750-5f29-ba39-f091dbc0ca37'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Quel milieu le roman peint-il principalement ?', 'mcq', '["La presse et la spéculation sous la IIIe République","Le monde paysan","L’armée coloniale seulement","L’Église"]'::jsonb, 0, 'L’affaire du Maroc y montre les liens entre journal, politique et argent.', 5),
    ('5352aa0d-6a5e-5160-ad10-ecce710e9f99'::uuid, 'd384fd2f-ac2c-5981-a8d2-acaa5c3e70b6'::uuid, 'Bel-Ami doit sa réussite à son talent d’écrivain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne sait pas écrire : ce sont les femmes et les circonstances qui le portent.', 6),
    ('be70d3ef-b997-5d9a-a592-aa6c8e5e6fc3'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Qui est Solal ?', 'mcq', '["Un haut fonctionnaire de la Société des Nations à Genève","Un banquier parisien","Un écrivain suisse","Un médecin"]'::jsonb, 0, 'Sa position sociale et sa judéité sont au cœur du roman.', 1),
    ('2f46bfee-2105-5d76-8cfe-08486e7886d0'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Comment Solal séduit-il Ariane la seconde fois ?', 'mcq', '["En revenant en séducteur, après avoir été repoussé déguisé en vieillard","En la sauvant d’un accident","Par une correspondance secrète","En achetant sa maison"]'::jsonb, 0, 'La séduction est une démonstration sur la vanité de l’amour.', 2),
    ('3ac8b2db-158d-572d-b0cc-9afd30a7c3d8'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Qui est Adrien Deume ?', 'mcq', '["Le mari d’Ariane, petit fonctionnaire médiocre","Le frère de Solal","Un diplomate anglais","Le père d’Ariane"]'::jsonb, 0, 'Solal le fait promouvoir pour l’éloigner.', 3),
    ('e69f9017-b613-5d22-8858-019bdc9d3351'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Qu’arrive-t-il à la passion des amants sur la Côte d’Azur ?', 'mcq', '["Elle s’étiole dans les rituels, la jalousie et l’ennui","Elle se renforce","Elle se transforme en amitié","Elle est interrompue par la guerre"]'::jsonb, 0, 'Coupée du monde, elle meurt de sa propre intensité.', 4),
    ('455511c2-a0d4-571a-a02a-6e788655e55f'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Par le double suicide des amants","Par le retour d’Ariane auprès d’Adrien","Par le mariage de Solal et Ariane","Par la fuite de Solal seul"]'::jsonb, 0, 'La fin est annoncée par tout le mouvement du livre.', 5),
    ('c9dc1f02-c302-5e98-bd27-9935c2c77eb3'::uuid, 'efd7be13-b532-56c3-ba5f-d198cc2ac416'::uuid, 'Le roman est uniquement lyrique et sérieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il alterne lyrisme, satire féroce de la bureaucratie et comédie des « Valeureux ».', 6),
    ('1a8eb196-169b-593c-bce9-dc19bba995d2'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'Pourquoi Titus renvoie-t-il Bérénice ?', 'mcq', '["Rome n’accepte pas qu’un empereur épouse une reine étrangère","Il ne l’aime plus","Elle a trahi Rome","Il aime une autre femme"]'::jsonb, 0, 'Le devoir l’emporte sur l’amour, sans que l’amour cesse.', 1),
    ('ad429cc7-7a98-5337-8a33-9b26ab84f244'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'Qui est Antiochus ?', 'mcq', '["Le roi de Comagène, qui aime Bérénice en silence","Le frère de Titus","Un sénateur romain","Le père de Bérénice"]'::jsonb, 0, 'Il espère un instant, et repart lui aussi seul.', 2),
    ('25137728-d258-5486-b8a5-5eaacded8f01'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'Combien de personnages meurent dans la pièce ?', 'mcq', '["Aucun","Un","Deux","Trois"]'::jsonb, 0, 'La tragédie est entièrement intérieure.', 3),
    ('033fd8b7-2aa4-5a47-9f57-00b9367120fd'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'De quelle source Racine tire-t-il son sujet ?', 'mcq', '["Cinq lignes de Suétone","Un poème d’Ovide","Une pièce grecque","Une chronique médiévale"]'::jsonb, 0, '« Invitus invitam dimisit » : il la renvoya malgré lui, malgré elle.', 4),
    ('5b3bc361-200e-5b61-8876-963e5122f5c5'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'Quelle formule Racine emploie-t-il dans sa préface ?', 'mcq', '["« Une tristesse majestueuse »","« Le sang appelle le sang »","« La passion est un poison »","« Rien de trop »"]'::jsonb, 0, 'Elle justifie une tragédie sans mort ni violence.', 5),
    ('5046600b-cf83-5529-b5b6-587140bd4a3e'::uuid, '24abfb81-ce50-545c-8b85-aec53aa58a8b'::uuid, 'Bérénice se donne la mort à la fin de la pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle refuse de se tuer et part : les trois personnages restent vivants et séparés.', 6),
    ('4c7c3bc1-499c-53dd-a4c2-3b405daa2a26'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'Quel âge a Françoise Sagan quand elle écrit ce roman ?', 'mcq', '["Dix-huit ans","Vingt-cinq ans","Trente ans","Vingt et un ans"]'::jsonb, 0, 'Publié en 1954, il fit scandale et lui valut le prix des Critiques.', 1),
    ('7fb2fa0d-c2ff-5a59-be9f-31d1b7cb587d'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'Qui est Anne Larsen ?', 'mcq', '["Une amie de la mère morte, que le père veut épouser","La sœur de Cécile","La maîtresse de Cyril","La gouvernante"]'::jsonb, 0, 'Sa rigueur menace la vie légère de Cécile et de son père.', 2),
    ('5bbb47a7-96ff-5420-8cfa-0f5561d13031'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'Quelle machination Cécile organise-t-elle ?', 'mcq', '["Faire croire à son père qu’Elsa et Cyril sont amants","Cacher une lettre d’Anne","Fuir avec Cyril","Ruiner son père"]'::jsonb, 0, 'Elle veut réveiller la jalousie de Raymond, et elle y parvient trop bien.', 3),
    ('3708a540-fb0b-591b-98af-a931849c8c38'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Anne part en voiture et se tue","Anne épouse Raymond","Cécile part étudier à Paris","Cyril épouse Elsa"]'::jsonb, 0, 'Accident ou suicide : le roman ne tranche pas.', 4),
    ('c01515d8-01f4-52ff-858c-b002170a5605'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'D’où vient le titre du roman ?', 'mcq', '["D’un poème de Paul Éluard","D’une chanson populaire","D’un vers de Baudelaire","D’une lettre de Sagan"]'::jsonb, 0, 'Le poème donne aussi le ton du récit.', 5),
    ('ce688039-3a0c-568a-bef5-b3aece7e4825'::uuid, '7cab7cd0-678e-581d-a569-2c9195f41e90'::uuid, 'Le roman fut immédiatement salué comme un livre moral.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa liberté de mœurs et son absence de remords firent scandale.', 6),
    ('83bf44ae-063c-5bb7-8a61-675d72ef01d0'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'Qui est Boubouroche ?', 'mcq', '["Un brave homme naïf trompé par sa maîtresse Adèle","Un militaire de carrière","Un fonctionnaire de bureau","Un avocat"]'::jsonb, 0, 'Il l’entretient depuis huit ans.', 1),
    ('8bc594c4-ab2e-5b7a-b6fe-216f6f221308'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'Que découvre Boubouroche chez Adèle ?', 'mcq', '["Un homme caché dans le placard","Des lettres compromettantes","Une valise prête pour un départ","Un enfant caché"]'::jsonb, 0, 'Le voisin l’avait prévenu.', 2),
    ('0ed7a3e8-4a49-5481-9618-7fa7a32a38ef'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'Comment Adèle réagit-elle ?', 'mcq', '["Elle se dit outragée et retourne la situation","Elle avoue tout","Elle s’enfuit","Elle demande pardon"]'::jsonb, 0, 'Elle invente une explication invraisemblable, et il la croit.', 3),
    ('ad2f5900-af82-55dd-a734-5ef7c86c61a5'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'D’où vient le comique de la pièce ?', 'mcq', '["De l’aveuglement volontaire de Boubouroche","D’un quiproquo sur les noms","De déguisements successifs","D’un jeu de mots répété"]'::jsonb, 0, 'Il choisit d’être trompé parce que la vérité coûterait trop cher.', 4),
    ('230736e4-61fa-5dbb-bd5f-844b32bdaae9'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'Quel milieu Courteline peint-il habituellement ?', 'mcq', '["La petite bourgeoisie, les bureaux et les casernes","La haute aristocratie","Le monde paysan","Les milieux artistiques"]'::jsonb, 0, 'Messieurs les ronds-de-cuir en est le meilleur exemple.', 5),
    ('d6f0a30b-a13c-5de7-bc4f-29d7fb5d91ba'::uuid, '39bd760c-47ca-54ca-b3f0-392d903bdef5'::uuid, 'La pièce se termine par la rupture des amants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est Boubouroche qui demande pardon : le retournement est complet.', 6),
    ('e39a4612-2381-5e94-8a47-b2bb0215a2ea'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'Pendant quelle guerre se déroule la nouvelle ?', 'mcq', '["La guerre franco-prussienne de 1870","La Première Guerre mondiale","Les guerres napoléoniennes","La guerre de Crimée"]'::jsonb, 0, 'La diligence quitte Rouen occupée pour Le Havre.', 1),
    ('b96b1688-f4ca-5604-bd38-a1a68d0e84b6'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'Qui est Boule de suif ?', 'mcq', '["Une prostituée nommée Élisabeth Rousset","Une aristocrate déchue","Une religieuse","Une commerçante rouennaise"]'::jsonb, 0, 'Elle est la seule à agir par patriotisme.', 2),
    ('dbbe020c-d55d-5d0b-8a91-f9df2c950952'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'Qu’exige l’officier prussien ?', 'mcq', '["Passer la nuit avec Boule de suif pour laisser partir la voiture","Une rançon","Les papiers des voyageurs","La confiscation des chevaux"]'::jsonb, 0, 'Elle refuse d’abord, puis cède sous la pression des autres voyageurs.', 3),
    ('b425d2f6-2088-51c1-93df-6c309c58a0cc'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'Comment les voyageurs traitent-ils Boule de suif au retour ?', 'mcq', '["Ils l’ignorent et mangent devant elle sans rien lui offrir","Ils la remercient chaleureusement","Ils lui offrent de l’argent","Ils la dénoncent aux Prussiens"]'::jsonb, 0, 'La symétrie avec le partage du début est le cœur de la nouvelle.', 4),
    ('e28acbd2-3760-5adf-8eae-901bafab1641'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'Dans quel recueil la nouvelle a-t-elle paru ?', 'mcq', '["Les Soirées de Médan","Contes de la bécasse","Le Horla","La Maison Tellier"]'::jsonb, 0, 'Recueil collectif du groupe naturaliste, autour de Zola.', 5),
    ('66c59d43-9e79-5edf-bd28-4678c28b1599'::uuid, 'cb24f7c8-52d4-5bfb-836c-8a78b9508234'::uuid, 'La nouvelle fait l’éloge du patriotisme des bourgeois.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle dénonce leur hypocrisie : seule la prostituée agit par patriotisme.', 6),
    ('972622b7-ceef-53cc-871c-0a4b04066d0a'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Comment Racine désigne-t-il Néron dans sa préface ?', 'mcq', '["Un « monstre naissant »","Un tyran accompli","Un prince éclairé","Un empereur malheureux"]'::jsonb, 0, 'La pièce montre le basculement, pas le crime installé.', 1),
    ('8c8593bd-1c85-517e-b0c7-81a14fefc0da'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Qui est Agrippine ?', 'mcq', '["La mère de Néron, qui veut gouverner à travers lui","La femme de Britannicus","La sœur de Junie","Une conseillère de Claude"]'::jsonb, 0, 'Elle a fait son fils empereur et prétend le tenir.', 2),
    ('e43f7c32-2668-5004-a346-b714d3a88381'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Quelle scène cruelle Néron impose-t-il à Junie ?', 'mcq', '["Repousser Britannicus devant lui, caché, sans rien laisser paraître","Assister à l’exécution de son frère","Renoncer publiquement à sa naissance","Épouser Narcisse"]'::jsonb, 0, 'C’est l’une des scènes les plus célèbres du théâtre français.', 3),
    ('db19257d-2a62-513e-9e7e-bdbfcd0ffcb5'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Quels sont les deux conseillers opposés de Néron ?', 'mcq', '["Burrhus et Narcisse","Sénèque et Tacite","Acomat et Osmin","Créon et Tirésias"]'::jsonb, 0, 'L’honnête homme contre le traître : Néron choisit le second.', 4),
    ('a462eca7-7bf9-5171-aab6-a4276a272431'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Comment Britannicus meurt-il ?', 'mcq', '["Empoisonné lors d’un banquet de réconciliation","Poignardé dans le palais","Exilé puis assassiné","Il ne meurt pas"]'::jsonb, 0, 'Le crime scelle le basculement de Néron.', 5),
    ('fbd367d0-4f48-55e0-bf72-65cc2aeea3da'::uuid, 'b48168da-d776-5a89-98ca-26067a3f3332'::uuid, 'Le personnage central de la tragédie est la victime.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est Néron, le bourreau en formation, que la pièce observe.', 6),
    ('4d5e9c5b-1fdd-53b3-b834-436054e2108d'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'Qu’est-ce qui déclenche la transformation de Caligula ?', 'mcq', '["La mort de sa sœur Drusilla et la découverte de l’absurde","Une trahison politique","Une maladie","Un complot du Sénat"]'::jsonb, 0, '« Les hommes meurent et ne sont pas heureux. »', 1),
    ('6d21e51a-5532-514f-b467-28102db6ec06'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'Quelle conséquence Caligula tire-t-il de l’absurdité du monde ?', 'mcq', '["Il exerce une liberté totale, jusqu’au crime","Il abdique","Il se réfugie dans la religion","Il réforme l’Empire"]'::jsonb, 0, 'Il n’est pas fou : il est logique, et c’est cela qui terrifie.', 2),
    ('a47ffd6f-f49e-5c71-9c92-cee3f87aa4b6'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'Que réclame Caligula à ses proches ?', 'mcq', '["La lune","Une statue d’or","Un triomphe militaire","Le trésor du Sénat"]'::jsonb, 0, 'L’impossible, pour dire l’écart entre le désir et le monde.', 3),
    ('51aea20f-c58b-5c74-a95e-989828ee1489'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'Qui organise le complot contre lui ?', 'mcq', '["Cherea","Scipion","Cæsonia","Hélicon"]'::jsonb, 0, 'Il agit au nom d’un monde simplement vivable.', 4),
    ('d751f459-680a-5a5f-a614-a3c948080ebc'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'À quel cycle de l’œuvre de Camus la pièce appartient-elle ?', 'mcq', '["Le cycle de l’absurde","Le cycle de la révolte","Le cycle de l’amour","Aucun cycle"]'::jsonb, 0, 'Avec L’Étranger et Le Mythe de Sisyphe.', 5),
    ('166c793b-e700-5cd4-94bd-b89e3fdf5302'::uuid, 'f78d865b-ddbd-5c16-a5fa-096c9f24d54c'::uuid, 'Caligula meurt en reconnaissant son erreur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il crie « Je suis encore vivant ! » : la révolte se prolonge dans la mort.', 6),
    ('d96fdcaf-5dd0-5ea1-aa00-7ef226e609f9'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Quelle philosophie Pangloss enseigne-t-il ?', 'mcq', '["Tout est au mieux dans le meilleur des mondes possibles","Rien n’a de sens","L’homme est bon par nature","Le plaisir est le seul bien"]'::jsonb, 0, 'C’est l’optimisme leibnizien que le conte va démolir.', 1),
    ('3f9c8578-c2eb-5d9c-a340-f1870d8961e4'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Quelle catastrophe réelle Voltaire intègre-t-il au conte ?', 'mcq', '["Le tremblement de terre de Lisbonne","La peste de Marseille","L’incendie de Londres","La famine de 1709"]'::jsonb, 0, 'Elle avait profondément ébranlé Voltaire en 1755.', 2),
    ('9bf1e513-b33d-51fa-9c78-a8972ace41fb'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Que dénonce l’épisode du nègre de Surinam ?', 'mcq', '["L’esclavage sur lequel repose le commerce du sucre","La guerre entre les Bulgares et les Abares","L’Inquisition portugaise","La corruption des jésuites"]'::jsonb, 0, '« C’est à ce prix que vous mangez du sucre en Europe. »', 3),
    ('126360d4-8c7a-54bc-8961-1c894c8e0d35'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Qu’est-ce que l’Eldorado dans le conte ?', 'mcq', '["Un pays idéal que Candide finit par quitter","Une ville détruite par la guerre","Un couvent espagnol","Un navire marchand"]'::jsonb, 0, 'L’utopie ne retient pas Candide : le bonheur parfait l’ennuie.', 4),
    ('cedad9cc-f90d-5d41-9132-5c0a146db4e5'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Par quelle formule le conte se termine-t-il ?', 'mcq', '["« Il faut cultiver notre jardin »","« Tout est bien qui finit bien »","« Écrasons l’infâme »","« Le meilleur des mondes »"]'::jsonb, 0, 'Renoncer aux systèmes et agir : la conclusion est encore discutée.', 5),
    ('09f7bae8-1b1a-58fc-8a8e-56b65287dad4'::uuid, 'c3b0e451-33a4-5a4c-9424-9e477bf971fd'::uuid, 'Candide est un roman réaliste aux personnages fouillés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un conte philosophique : récit rapide, personnages schématiques, ironie constante.', 6),
    ('325d2f48-4670-5788-9b7a-278528ea436d'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'À quel mouvement le recueil est-il lié ?', 'mcq', '["Le surréalisme","Le Parnasse","Le symbolisme","Le naturalisme"]'::jsonb, 0, 'Éluard en est la grande voix lyrique.', 1),
    ('5c5d65fb-62a0-5d99-984b-599d70b3b49e'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'En quelle année paraît Capitale de la douleur ?', 'mcq', '["1926","1913","1945","1935"]'::jsonb, 0, 'Le titre a été trouvé en dernier.', 2),
    ('27533e88-29b5-57cf-8abf-d80973a6f8c8'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'Quel vers célèbre ouvre l’un des poèmes du recueil ?', 'mcq', '["« La courbe de tes yeux fait le tour de mon cœur »","« Sous le pont Mirabeau »","« Je vous salue ma France »","« Heureux qui comme Ulysse »"]'::jsonb, 0, 'L’image simple y produit un déplacement immense.', 3),
    ('6c6880f3-cebb-5886-9fff-aadb6d9a574d'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'Quelle image est devenue le manifeste de l’image surréaliste ?', 'mcq', '["« La terre est bleue comme une orange »","« Mon beau navire ô ma mémoire »","« Je est un autre »","« Le ciel est par-dessus le toit »"]'::jsonb, 0, 'Rapprochement de deux réalités éloignées, sans justification logique.', 4),
    ('73dac932-4c35-5ea5-8bff-b50a508f29d6'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'Quelle est la particularité formelle des poèmes ?', 'mcq', '["Vers libres, sans ponctuation, syntaxe limpide","Sonnets réguliers","Alexandrins rimés","Poèmes en prose exclusivement"]'::jsonb, 0, 'Peu de mots, souvent brefs, pour une image inattendue.', 5),
    ('e45f991a-fee2-5107-8a24-50bbc2b85ba2'::uuid, 'ea8af410-e7b0-5838-bcee-4358e83e82de'::uuid, 'Le surréalisme d’Éluard exclut le lyrisme amoureux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au contraire : il met les images surréalistes au service de l’amour.', 6),
    ('e0641ca9-704a-50c8-aaf2-ca38b2913336'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Qui raconte l’essentiel de l’histoire de Carmen ?', 'mcq', '["Don José, la veille de son exécution","Carmen elle-même","Un narrateur omniscient","Le mari de Carmen"]'::jsonb, 0, 'Le récit est enchâssé dans celui d’un voyageur archéologue.', 1),
    ('d9ab0528-e3a9-5eb1-9c88-ce54c9ab9609'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Que devient don José après avoir laissé s’échapper Carmen ?', 'mcq', '["Il déserte et devient contrebandier","Il est promu officier","Il rentre en Navarre","Il entre dans les ordres"]'::jsonb, 0, 'La chute est progressive : désertion, meurtres, banditisme.', 2),
    ('6d53fa4d-82ba-5fd8-9b2f-427c131328c9'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Pourquoi Carmen refuse-t-elle de revenir à don José ?', 'mcq', '["Parce qu’elle ne l’aime plus et refuse de mentir","Parce qu’elle a peur de lui","Parce qu’elle aime son mari","Parce qu’elle veut quitter l’Espagne"]'::jsonb, 0, '« Carmen sera toujours libre » : elle préfère mourir que feindre.', 3),
    ('b66caf71-9ac3-5dd1-be6e-9e945bcdba6d'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Comment la nouvelle se termine-t-elle ?', 'mcq', '["Don José poignarde Carmen puis se livre","Carmen s’enfuit en Afrique","Don José est gracié","Ils s’enfuient ensemble"]'::jsonb, 0, 'Il raconte ensuite son histoire au narrateur, en prison.', 4),
    ('531826ea-3df3-5ee2-b6bb-6978982e616c'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Quelle œuvre a rendu le récit universellement célèbre ?', 'mcq', '["L’opéra de Bizet, en 1875","Un roman de Zola","Une pièce de Hugo","Un film muet"]'::jsonb, 0, 'L’opéra a largement éclipsé le texte de Mérimée.', 5),
    ('3b44db9f-269c-51e4-8a27-8d59b86c25ed'::uuid, '7b8c8eaa-994c-5167-b2a5-e0a245b3fe19'::uuid, 'Carmen est présentée comme une simple séductrice sans volonté propre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est le personnage qui refuse absolument d’appartenir à quiconque.', 6),
    ('7123bf74-c69a-5108-b856-862c1ff04a4e'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'Pourquoi Émilie veut-elle la mort d’Auguste ?', 'mcq', '["Il a fait tuer son père lors des proscriptions","Il l’a répudiée","Il a exilé Cinna","Il a trahi Rome"]'::jsonb, 0, 'Elle exige la vengeance comme prix de sa main.', 1),
    ('29db5da3-1144-5097-9389-1b858e64c472'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'Qui trahit le complot ?', 'mcq', '["Maxime","Émilie","Livie","Euphorbe seul"]'::jsonb, 0, 'Amoureux d’Émilie, il révèle tout à Auguste.', 2),
    ('8cb7a0ef-aa11-5838-883e-834c29a54d38'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'Que demande Auguste à Cinna et Maxime avant de découvrir le complot ?', 'mcq', '["S’il doit abdiquer","De partir en campagne","De juger Émilie","De rédiger ses mémoires"]'::jsonb, 0, 'Cinna plaide le maintien de l’Empire… pour garder un tyran à tuer.', 3),
    ('c7d1149d-7c0e-57fa-80ea-03abaa0d799c'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'Que décide Auguste à la fin ?', 'mcq', '["Il pardonne à tous les conjurés","Il les fait exécuter","Il abdique","Il exile Cinna"]'::jsonb, 0, '« Soyons amis, Cinna, c’est moi qui t’en convie. »', 4),
    ('4a3a3866-6e48-5767-9443-e61719d08810'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'Quelle formule résume la victoire d’Auguste ?', 'mcq', '["« Je suis maître de moi comme de l’univers »","« Rome n’est plus dans Rome »","« Va, cours, vole et nous venge »","« À vaincre sans péril… »"]'::jsonb, 0, 'La clémence est la maîtrise de soi, donc la vraie souveraineté.', 5),
    ('41c94f39-f763-5a17-b110-ffa380b1e883'::uuid, '1a6fb589-5978-50cc-b435-4f7bf9f2b69a'::uuid, 'La clémence d’Auguste est présentée comme une faiblesse politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’acte le plus fort de la pièce : il fonde son autorité.', 6),
    ('20d9f9a7-abd4-5ade-96f6-e8f0f65e0115'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'Quel continent le ballon traverse-t-il ?', 'mcq', '["L’Afrique, d’est en ouest","L’Amérique du Sud","L’Asie centrale","L’Australie"]'::jsonb, 0, 'Le Victoria décolle de Zanzibar et atteint le Sénégal.', 1),
    ('9c0fee62-dd38-50cb-b270-387150c460a1'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'Quelle invention permet de diriger le ballon ?', 'mcq', '["La variation de température du gaz, qui fait monter ou descendre","Une hélice à vapeur","Un gouvernail latéral","Des ballasts d’eau seulement"]'::jsonb, 0, 'C’est le ressort scientifique du livre.', 2),
    ('0eb73350-dbf4-5f17-96fd-a65f29eac20a'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'Qui accompagne le docteur Fergusson ?', 'mcq', '["Le chasseur Dick Kennedy et le domestique Joe","Deux savants allemands","Un capitaine et un mousse","Sa fille et son gendre"]'::jsonb, 0, 'Le trio suit la formule des romans d’aventures de Verne.', 3),
    ('2a648abd-f19f-5c4a-99a0-22c4263ad196'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'À quel cycle appartient le roman ?', 'mcq', '["Les Voyages extraordinaires","Les Rougon-Macquart","La Comédie humaine","Les Contes du lundi"]'::jsonb, 0, 'C’est le premier volume du cycle publié par Hetzel.', 4),
    ('20faa528-2848-5f4b-9a49-ca9101db2681'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'Quelle est la formule éditoriale d’Hetzel ?', 'mcq', '["Instruire en amusant","Épouvanter le lecteur","Publier des romans-feuilletons policiers","Défendre la science pure"]'::jsonb, 0, 'Elle explique les passages didactiques du roman.', 5),
    ('18ff595f-4001-51e0-9f6e-15ff77d6d425'::uuid, 'e9556fb7-01a5-5de2-9649-1aaca33e8945'::uuid, 'Le regard porté sur l’Afrique est celui d’un observateur neutre et moderne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est marqué par les préjugés coloniaux de son temps : c’est à signaler dans un devoir.', 6),
    ('d4912481-564c-59e6-acf2-976ee1647f54'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Que contient le roman Clélie, devenu célèbre à lui seul ?', 'mcq', '["La carte de Tendre","Le portrait de Louis XIV","Une préface de Corneille","Un dictionnaire des passions"]'::jsonb, 0, 'Une allégorie gravée du parcours amoureux, née d’un jeu de salon.', 1),
    ('15207444-71ad-59ee-bb84-5cfa238d5b1f'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Quelles sont les trois villes de Tendre ?', 'mcq', '["Tendre-sur-Estime, Tendre-sur-Reconnaissance, Tendre-sur-Inclination","Tendre-sur-Amour, Tendre-sur-Passion, Tendre-sur-Désir","Tendre-la-Belle, Tendre-la-Fière, Tendre-la-Douce","Tendre-Nord, Tendre-Sud, Tendre-Centre"]'::jsonb, 0, 'Trois chemins pour trois façons de naître à l’amour.', 2),
    ('59c23507-127e-5cf1-9255-82c6a4e3c46d'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Que faut-il éviter sur la carte de Tendre ?', 'mcq', '["Le lac d’Indifférence et la mer d’Inimitié","La rivière de Tendresse","Le village de Sincérité","Le bourg de Petits-Soins"]'::jsonb, 0, 'Les écueils du parcours amoureux y sont figurés en géographie.', 3),
    ('7bde0574-a4f1-5324-b6fe-87aade34fc68'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Dans quel cadre historique le roman se situe-t-il ?', 'mcq', '["La Rome des débuts de la République","La Perse antique","La Grèce d’Alexandre","L’Égypte ptolémaïque"]'::jsonb, 0, 'Comme Artamène, l’Antiquité sert de décor à un propos contemporain.', 4),
    ('39493495-adf0-5296-b92f-24265726038c'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Quelle conception de l’amour Madeleine de Scudéry défend-elle ?', 'mcq', '["Une relation fondée sur l’estime, la conversation et le mérite","Le mariage arrangé par les familles","La passion violente et exclusive","Le renoncement religieux"]'::jsonb, 0, 'C’est le cœur de la préciosité, souvent caricaturée par Molière.', 5),
    ('64b0ea61-9606-54d2-81a5-5f9c2c629aca'::uuid, '58dcd11e-6e27-54fb-b858-9c2f246e5eb6'::uuid, 'Le roman tient en un seul volume.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en compte dix, publiés entre 1654 et 1660.', 6),
    ('0accb26d-b057-56ff-a8f2-5ff9fa34e6de'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Où se déroule le récit ?', 'mcq', '["En Corse","En Sicile","En Sardaigne","Dans les Pyrénées"]'::jsonb, 0, 'Mérimée avait visité l’île comme inspecteur des Monuments historiques.', 1),
    ('23351a44-b6b9-5c4a-838b-04b4cf74724f'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Qu’est-ce que la vendetta ?', 'mcq', '["La vengeance familiale imposée par la coutume","Un chant de mariage","Un tribunal local","Une fête religieuse"]'::jsonb, 0, 'Elle s’oppose à la justice de l’État, que représente Orso.', 2),
    ('d68baf63-1fef-5fd6-b981-e08600d318c4'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Qui pousse Orso à venger son père ?', 'mcq', '["Sa sœur Colomba","Lydia Nevil","Le préfet","Le vieux Barricini"]'::jsonb, 0, 'Elle improvise des voceri, monte des preuves et manœuvre sans relâche.', 3),
    ('f5c5af4f-ba82-5c79-ae3e-3e18bb49d834'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Que veut Orso au retour en Corse ?', 'mcq', '["La justice plutôt que la vengeance","La vendetta immédiate","Vendre ses terres","Rejoindre l’armée anglaise"]'::jsonb, 0, 'Sa formation continentale l’oppose à la coutume de l’île.', 4),
    ('00188d9d-14d8-5be1-8b4e-12b287aee504'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Comment Orso tue-t-il les deux fils Barricini ?', 'mcq', '["En légitime défense, lors d’une embuscade","Par traîtrise, la nuit","En duel réglé","Il ne les tue pas"]'::jsonb, 0, 'La coutume obtient ainsi ce qu’elle voulait, sans qu’Orso se renie tout à fait.', 5),
    ('c57e2fde-5b83-51ce-9761-a07bb19cff4f'::uuid, 'fbadd96d-0610-5b51-b490-340f9449104e'::uuid, 'Colomba est un personnage secondaire du récit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle donne son titre à l’œuvre et se révèle plus déterminée que tous les hommes.', 6),
    ('80d4568e-7054-5996-84f0-d345f7f192d4'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'En quelle année les Contes paraissent-ils ?', 'mcq', '["1697","1667","1720","1812"]'::jsonb, 0, 'Sous le nom du fils de Perrault, Pierre Darmancour.', 1),
    ('11eb6bd4-d5f8-5860-b0d8-96ea5c93a02a'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'Combien de contes le recueil compte-t-il ?', 'mcq', '["Huit","Trois","Douze","Vingt"]'::jsonb, 0, 'De La Belle au bois dormant au Petit Poucet.', 2),
    ('ae75e2f9-1bac-52c7-ad26-bac8d4f6e74c'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'Par quoi chaque conte se termine-t-il ?', 'mcq', '["Une ou deux moralités en vers","Un dialogue","Une gravure","Une prière"]'::jsonb, 0, 'Souvent ironiques, parfois en décalage avec le récit.', 3),
    ('84ef4a46-aced-5bdd-b568-e942f04fd6fb'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'Comment se termine Le Petit Chaperon rouge chez Perrault ?', 'mcq', '["La fillette est mangée : il n’y a pas de sauvetage","Le chasseur la sauve","Elle s’échappe seule","Le loup est puni par les villageois"]'::jsonb, 0, 'La fin heureuse est une invention des frères Grimm.', 4),
    ('1b9a233a-1e9b-53bd-be11-acd5f268c33f'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'À quelle querelle littéraire Perrault participe-t-il ?', 'mcq', '["La querelle des Anciens et des Modernes, du côté des Modernes","La querelle du Cid","La querelle des bouffons","La querelle du théâtre"]'::jsonb, 0, 'Écrire des contes français est un geste polémique contre l’imitation de l’Antiquité.', 5),
    ('c5e67af0-7da3-5357-9b69-7639017607cc'::uuid, '7476506b-9f00-5b3b-a4d9-e058841f5342'::uuid, 'Perrault a inventé de toutes pièces ces récits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il met par écrit des récits oraux et populaires, dans une langue de cour.', 6),
    ('50492bd0-8526-551b-b3ae-38f008e2e3a5'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'En quelle année Gide et Valéry se rencontrent-ils ?', 'mcq', '["En 1890, à Montpellier","En 1910, à Paris","En 1900, à Alger","En 1925, à Genève"]'::jsonb, 0, 'Ils ont alors une vingtaine d’années.', 1),
    ('ced2c070-0c8d-533f-8dfe-cc0f6bf4c380'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'Combien de temps dure leur correspondance ?', 'mcq', '["Plus d’un demi-siècle","Cinq ans","Vingt ans","Toute leur enfance"]'::jsonb, 0, 'Jusqu’à la mort de Valéry en 1945.', 2),
    ('9dbb0afc-764f-5a85-8bdd-6996df724091'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'Quel poète domine leurs débuts communs ?', 'mcq', '["Mallarmé","Hugo","Baudelaire","Verlaine"]'::jsonb, 0, 'Ils fréquentent ses « mardis » de la rue de Rome.', 3),
    ('e9067c41-ef0e-5b41-af92-0fe5d2b7e92f'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'Que fait Valéry pendant sa longue période de silence poétique ?', 'mcq', '["Il se consacre aux mathématiques et à ses Cahiers","Il voyage en Afrique","Il écrit des romans","Il enseigne à la Sorbonne"]'::jsonb, 0, 'Vingt ans de retrait avant La Jeune Parque.', 4),
    ('597b6c9c-312a-5af5-bcd0-bf0d8695617a'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'Quelle revue Gide contribue-t-il à fonder ?', 'mcq', '["La NRF","Le Mercure de France","Les Temps modernes","La Revue des Deux Mondes"]'::jsonb, 0, 'Elle deviendra centrale dans la vie littéraire française.', 5),
    ('7d225520-46cc-5da4-92ef-cb94f94cbd60'::uuid, '3252577d-a226-50da-bb3b-71b688d58114'::uuid, 'Une correspondance d’écrivains n’a aucun intérêt littéraire propre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un genre à part entière : elle donne accès à l’atelier et aux hésitations.', 6),
    ('3b524e5b-a729-54b1-afd2-42201b3bb8cf'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Qu’est-ce qui empêche Cyrano de déclarer son amour ?', 'mcq', '["Son nez, qu’il croit rédhibitoire","Sa pauvreté","Un serment militaire","La différence de rang"]'::jsonb, 0, 'Il se croit condamné à n’être jamais aimé.', 1),
    ('59248788-47a9-55f6-8452-898ab18f4991'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Que fait Cyrano pour Christian ?', 'mcq', '["Il lui prête ses mots, ses lettres et sa voix","Il le fait nommer capitaine","Il l’aide à s’enfuir avec Roxane","Il le provoque en duel"]'::jsonb, 0, 'La scène du balcon en est le sommet.', 2),
    ('d647f7f4-c2b5-5742-b320-2f236b29d567'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Où Christian meurt-il ?', 'mcq', '["Au siège d’Arras","À Paris, en duel","À l’hôtel de Bourgogne","En Gascogne"]'::jsonb, 0, 'Cyrano lui écrivait chaque jour au nom de leur amour.', 3),
    ('a35ec7b4-3c5f-5f89-85d6-6fc770b290fd'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Quand Roxane comprend-elle la vérité ?', 'mcq', '["Quinze ans plus tard, en entendant Cyrano lire la lettre de nuit","Dès la scène du balcon","À la mort de Christian","Jamais"]'::jsonb, 0, 'Il la lit par cœur alors qu’il fait trop sombre pour lire.', 4),
    ('ced0c469-dc8c-52d0-860f-e739601e0d03'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Quel est le dernier mot de la pièce ?', 'mcq', '["« Mon panache »","« Roxane »","« Adieu »","« Le nez »"]'::jsonb, 0, 'Le panache : la manière, quand tout le reste est perdu.', 5),
    ('cc363460-3900-567c-83ca-8d42a7fc179a'::uuid, 'd721b973-ed02-5dbf-9c45-bada827d24ec'::uuid, 'Cyrano de Bergerac est un personnage entièrement inventé par Rostand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Savinien de Cyrano de Bergerac fut un écrivain libertin bien réel du XVIIe siècle.', 6),
    ('e0901e3b-da7f-5496-96bb-7e5138df7437'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'Quels sont les trois types de gouvernement selon Montesquieu ?', 'mcq', '["République, monarchie, despotisme","Démocratie, oligarchie, tyrannie","Empire, royaume, cité","Théocratie, république, empire"]'::jsonb, 0, 'Chacun a son ressort : la vertu, l’honneur, la crainte.', 1),
    ('47fbb0d5-fb17-5167-8845-2d35d67539f2'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'Quel principe fait la célébrité de l’ouvrage ?', 'mcq', '["La séparation des pouvoirs","La souveraineté du peuple","Le contrat social","Le droit naturel"]'::jsonb, 0, 'Il passera dans la Constitution américaine et dans la Déclaration de 1789.', 2),
    ('5a32e80c-277c-5ee6-99b6-5632ffe7470d'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'Quel pays inspire la réflexion sur la séparation des pouvoirs ?', 'mcq', '["L’Angleterre","La Hollande","Venise","La Suisse"]'::jsonb, 0, 'Montesquieu y avait séjourné et observé les institutions.', 3),
    ('727d1d74-1df2-51e9-bd74-5f2bde999e6d'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'Qu’est-ce que la théorie des climats ?', 'mcq', '["L’idée que climat et milieu influencent les lois et les mœurs","Une théorie sur les saisons agricoles","Un traité de météorologie","Une classification des peuples par la religion"]'::jsonb, 0, 'Contestée aujourd’hui, elle fonde une approche comparatiste du droit.', 4),
    ('bf6f354a-7f72-53dd-b69f-7cc816e511bb'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'Comment Montesquieu dénonce-t-il l’esclavage ?', 'mcq', '["Par un chapitre ironique feignant de le défendre","Par un plaidoyer direct devant le Parlement","Par une pétition","Il ne l’aborde pas"]'::jsonb, 0, '« De l’esclavage des nègres » est un modèle d’antiphrase.', 5),
    ('461b5c77-9c56-5f69-a906-5fc905b419bf'::uuid, '885db6b5-b949-5821-84e7-ee73152cdf19'::uuid, 'L’ouvrage a été publié sous le nom de son auteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Publication anonyme à Genève, en 1748, pour éviter la censure.', 6),
    ('bca70a5f-8421-5ca8-af2d-c5769a6a9170'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Quel âge a Pic de la Mirandole quand il écrit ce discours ?', 'mcq', '["Vingt-trois ans","Quarante ans","Cinquante ans","Trente-cinq ans"]'::jsonb, 0, 'Il devait ouvrir une dispute publique à Rome sur neuf cents thèses.', 1),
    ('dbdc1166-44f3-5de6-ba76-5e0a943643fd'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Que dit le texte de la nature de l’homme ?', 'mcq', '["Il n’a pas de nature fixe : il est ce qu’il se fait","Il est par nature bon","Il est déterminé par son rang de naissance","Il est identique à l’animal"]'::jsonb, 0, 'C’est la première formulation nette de la liberté comme définition de l’humain.', 2),
    ('d37f6fbb-9a9c-594e-824c-1a255875a56c'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Pourquoi la dispute prévue n’a-t-elle pas eu lieu ?', 'mcq', '["Le pape l’a interdite","L’auteur est mort avant","Les universités l’ont refusée","Elle a été reportée sans fin"]'::jsonb, 0, 'Le discours est publié après la mort de Pic.', 3),
    ('1826a302-23ac-56b0-a83c-5ceaee2942b3'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Quelle conséquence pédagogique découle de la thèse ?', 'mcq', '["Si l’homme se fait, l’éducation est décisive","L’éducation est inutile","Seule la grâce compte","Le savoir est réservé aux clercs"]'::jsonb, 0, 'C’est le programme même de l’humanisme.', 4),
    ('9a8e394e-2237-52f1-8b29-5519b1bfda02'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Quel projet intellectuel Pic défend-il ?', 'mcq', '["Concilier Platon, Aristote, la Kabbale et les Pères de l’Église","Rejeter toute philosophie païenne","Fonder une science expérimentale","Traduire la Bible en italien"]'::jsonb, 0, 'Il croit à la concorde des savoirs.', 5),
    ('6184a1b6-ccd5-5962-b38c-1336bc75defa'::uuid, '569715ae-955f-51c8-8c24-f09bb9f4d0e9'::uuid, 'Le texte est considéré comme un manifeste de l’humanisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il en est même le texte emblématique.', 6),
    ('e1d84fe7-e5d1-528c-aa30-57cf808cd737'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'Quel texte la Déclaration reprend-elle mot pour mot ?', 'mcq', '["La Déclaration des droits de l’homme et du citoyen de 1789","Le Contrat social","La Constitution de 1791","Le Code civil"]'::jsonb, 0, 'Le pastiche rend l’oubli des femmes immédiatement visible.', 1),
    ('7b6d27fa-4bcb-5404-ab7e-88cc0f809cd9'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'Que dit l’article X ?', 'mcq', '["La femme qui peut monter à l’échafaud doit pouvoir monter à la tribune","Toutes les femmes sont électrices","Le divorce est un droit","L’instruction est obligatoire"]'::jsonb, 0, 'Punie comme citoyenne, la femme doit être représentée comme telle.', 2),
    ('42f92a49-a0df-5c57-9eeb-90b9493f0fd9'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'À qui le postambule s’adresse-t-il ?', 'mcq', '["Aux femmes elles-mêmes","Au roi","À l’Assemblée","Aux juges"]'::jsonb, 0, '« Femme, réveille-toi » : il change complètement de registre.', 3),
    ('5edee373-ab65-5739-8006-617d27684544'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'Quel autre combat Olympe de Gouges a-t-elle mené ?', 'mcq', '["L’abolition de l’esclavage","La liberté du commerce","La réforme fiscale","La laïcité scolaire"]'::jsonb, 0, 'Sa pièce L’Esclavage des Noirs le montre.', 4),
    ('79deec5b-7cfe-56f0-91fc-b5c9f11ea9af'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'Quel sort connut l’autrice ?', 'mcq', '["Elle fut guillotinée en 1793","Elle mourut en exil","Elle fut oubliée mais épargnée","Elle vécut jusqu’à l’Empire"]'::jsonb, 0, 'L’article X en devient prophétique.', 5),
    ('7c384d01-63fc-5181-aaf1-4a69df20707e'::uuid, '015886d6-8d81-5729-b22f-2469acb5a54a'::uuid, 'Les Françaises ont obtenu le droit de vote peu après 1791.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faudra attendre 1944 : le texte n’a eu aucun effet légal immédiat.', 6),
    ('f7caa37c-f75e-5245-999b-985e2577a059'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Quel groupe de poètes ce manifeste représente-t-il ?', 'mcq', '["La Pléiade","Les Grands Rhétoriqueurs","Le Parnasse","Les surréalistes"]'::jsonb, 0, 'Ronsard, Du Bellay, Baïf, Jodelle et leurs compagnons.', 1),
    ('12990c82-0b3a-58e1-b5bd-f76789c199e8'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Quelle est la thèse centrale du texte ?', 'mcq', '["Le français peut égaler le latin et le grec, à condition d’être enrichi","Le latin doit rester la langue des lettres","Il faut créer une langue nouvelle","La poésie doit être orale"]'::jsonb, 0, 'Le français n’est pas pauvre par nature, mais par manque de culture.', 2),
    ('52a61c97-fb1c-5027-beef-6ee2f4bea066'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Par quel moyen principal enrichir la langue ?', 'mcq', '["L’imitation créatrice des Anciens et des Italiens","La traduction littérale","Le retour au vieux français","L’invention pure"]'::jsonb, 0, 'Faire en français ce qu’ils ont fait dans leur langue.', 3),
    ('47f29dd2-5abb-516f-9d27-a7c151eca3c0'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Quelles formes le manifeste recommande-t-il d’abandonner ?', 'mcq', '["Rondeaux, ballades et virelais","Sonnets et odes","Élégies et tragédies","Épîtres et satires"]'::jsonb, 0, 'Elles sont jugées médiévales et basses.', 4),
    ('e3d26109-4cf6-5fac-9651-c085efeb6ade'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Quelle ordonnance royale précède le texte de dix ans ?', 'mcq', '["Villers-Cotterêts, 1539","L’édit de Nantes, 1598","L’édit de Fontainebleau","La pragmatique sanction"]'::jsonb, 0, 'Elle impose le français dans les actes officiels : la langue devient nationale.', 5),
    ('052f6943-ba89-5c00-8ff7-6ac4787b27f6'::uuid, '21f05c63-98ea-5461-b0f3-609882989ce7'::uuid, 'Selon Du Bellay, l’inspiration suffit au poète.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut travailler, « limer et relimer » : la poésie est un métier.', 6),
    ('1ea40d46-6a05-5f23-9574-4d1bfb0146a8'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Qui sont George et Lennie ?', 'mcq', '["Deux ouvriers agricoles itinérants pendant la Grande Dépression","Deux frères propriétaires","Deux soldats démobilisés","Deux étudiants en fuite"]'::jsonb, 0, 'George protège Lennie, colosse doux et déficient mental.', 1),
    ('374c44e6-2a59-5200-82ef-b7d5ee9c9f0b'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Quel rêve partagent-ils ?', 'mcq', '["Acheter une petite ferme avec des lapins","Partir en Europe","Ouvrir un commerce en ville","Devenir contremaîtres"]'::jsonb, 0, 'Le rêve est répété comme une litanie tout au long du livre.', 2),
    ('f65814e7-62d9-5e38-ba5f-a99711ca8b55'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Que fait Lennie dans la grange ?', 'mcq', '["Il tue accidentellement la femme de Curley","Il vole de l’argent","Il libère les chevaux","Il se blesse gravement"]'::jsonb, 0, 'Il voulait seulement la faire taire, sans mesurer sa force.', 3),
    ('5c9ffdd9-4e59-5ec3-8a22-743ff3347e23'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["George tue Lennie pour lui épargner le lynchage","Lennie s’échappe","Les deux amis achètent la ferme","Curley pardonne"]'::jsonb, 0, 'Il lui raconte une dernière fois le rêve avant de tirer.', 4),
    ('bd0ae1ad-6ca4-54a3-831a-b2c6be17ab0b'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'D’où vient le titre du roman ?', 'mcq', '["D’un vers de Robert Burns sur les plans qui tournent mal","D’un proverbe américain","D’une chanson de cow-boys","De la Bible"]'::jsonb, 0, 'Les meilleurs plans des souris et des hommes échouent souvent.', 5),
    ('4ea3d6d4-685c-5840-a857-f1dfb1cf0d12'::uuid, 'eaa988b1-395c-54a2-be27-8b35a65ab2b2'::uuid, 'Le roman est construit comme une pièce de théâtre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Six chapitres comme six scènes, presque uniquement des dialogues : il fut aussitôt adapté.', 6),
    ('1a803b00-520a-51c1-ad0c-4b95375da441'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Quels sont les deux récits alternés du roman ?', 'mcq', '["Celui de Nour en 1909-1912 et celui de Lalla au XXe siècle","Deux récits contemporains parallèles","Un récit de guerre et un récit de voyage","Un récit d’enfance et un récit de vieillesse"]'::jsonb, 0, 'Le premier raconte la fin des hommes bleus, le second l’exil de leur descendante.', 1),
    ('474c1dc7-e914-5ffd-b1b3-331afc50b7ab'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Qui est Ma el Aïnine ?', 'mcq', '["Le cheikh qui guide les hommes bleus vers le nord","Le père de Lalla","Un officier français","Un marchand de Tanger"]'::jsonb, 0, 'Sa marche s’achève par le massacre des combattants.', 2),
    ('d20aae99-a451-54ef-9d44-b747042af6ca'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Où Lalla émigre-t-elle ?', 'mcq', '["À Marseille","À Paris","À Casablanca","En Espagne"]'::jsonb, 0, 'Elle y connaît la misère, puis un bref succès comme modèle.', 3),
    ('6f451d79-6561-5ea0-ba2e-ff2485f0dd1d'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Comment se termine le parcours de Lalla ?', 'mcq', '["Elle revient au désert et accouche sous un arbre","Elle reste en France","Elle épouse le photographe","Elle meurt à Marseille"]'::jsonb, 0, 'Le retour au désert referme le cercle des deux récits.', 4),
    ('8f174ca6-8580-5769-8568-2488dab12ff8'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'Quel prix Le Clézio a-t-il reçu en 2008 ?', 'mcq', '["Le prix Nobel de littérature","Le Goncourt","Le Renaudot","Le prix Femina"]'::jsonb, 0, 'Désert avait déjà installé sa notoriété en 1980.', 5),
    ('2d304b00-2a90-5828-97f2-606ca5f15c8b'::uuid, '99bd033c-e58a-56b7-a778-b530001e98b1'::uuid, 'La ville est décrite comme un refuge accueillant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle apparaît comme un désert plus hostile que le vrai.', 6),
    ('324219bb-b339-5bd7-8a14-3b3a1b7fcb16'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'Comment l’ouvrage est-il organisé ?', 'mcq', '["En articles courts classés par ordre alphabétique","En chapitres thématiques","En dialogues numérotés","En lettres fictives"]'::jsonb, 0, 'D’où le titre de « dictionnaire ».', 1),
    ('2b39b7ee-1fdc-59a9-8de5-c7ebd6866368'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'Pourquoi le format « portatif » est-il une arme ?', 'mcq', '["Petit et bon marché, il circule facilement et se cache","Il coûte cher, donc il fait sérieux","Il permet des articles très longs","Il évite la censure par son titre"]'::jsonb, 0, 'Contrairement aux gros volumes de l’Encyclopédie.', 2),
    ('23f5e6a7-b696-5a83-b62f-9f9cfdf8da56'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'Quelle est la cible principale de Voltaire ?', 'mcq', '["L’intolérance religieuse et la superstition","La monarchie constitutionnelle","Les sciences expérimentales","La poésie classique"]'::jsonb, 0, 'Le fanatisme y est comparé à une maladie contagieuse.', 3),
    ('32640123-3b23-568f-bc16-124eecb85fcf'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'Quels procédés Voltaire emploie-t-il dans ses articles ?', 'mcq', '["Ironie, fausse naïveté, dialogue et récit bref","Démonstrations mathématiques","Citations latines exclusivement","Sermons"]'::jsonb, 0, 'On ne combat pas un préjugé par un traité, mais par cent piqûres.', 4),
    ('1fd0ae20-c367-5b28-aaa0-8f7ef352514c'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'En quelle année l’ouvrage paraît-il ?', 'mcq', '["1764","1721","1748","1789"]'::jsonb, 0, 'Voltaire l’augmentera jusqu’en 1769.', 5),
    ('af688485-1985-504f-9926-1f820a5d94cb'::uuid, '4bb44ee6-872d-5eea-8a74-a74a8f63df18'::uuid, 'L’ouvrage fut publié avec l’autorisation des autorités.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Publié anonymement, il fut condamné et brûlé.', 6),
    ('de3b6642-09b0-5e95-9e1d-93c3c8a6dac9'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Quelle question le texte retourne-t-il ?', 'mcq', '["Non pas comment le tyran domine, mais pourquoi le peuple consent","Comment gouverner justement","Faut-il tuer le tyran","Quelle est la meilleure constitution"]'::jsonb, 0, 'C’est ce renversement qui fait la force du Discours.', 1),
    ('11943493-ce04-5277-bf78-74e08f9553ef'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Quelle solution La Boétie propose-t-il ?', 'mcq', '["Retirer son consentement, sans violence","Armer le peuple","Attendre un prince juste","Fuir le royaume"]'::jsonb, 0, 'Le colosse tombe si l’on retire le socle.', 2),
    ('cc29710b-faaa-5066-87ac-2cceb7d185f5'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Quelle est la première cause de la servitude ?', 'mcq', '["La coutume","La peur des armes","La misère","La religion"]'::jsonb, 0, 'On naît sous le joug et l’on croit qu’il est naturel.', 3),
    ('b963a121-75b2-5276-95e9-e5decffed5c9'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Comment le pouvoir se maintient-il selon La Boétie ?', 'mcq', '["Par une pyramide de complices intéressés","Par une armée permanente","Par la richesse du prince","Par l’ignorance seule"]'::jsonb, 0, 'Cinq ou six profitent, puis six cents, puis six mille.', 4),
    ('3dc4b55f-4036-5d1b-86d5-9426c0fdb513'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Quel écrivain était l’ami intime de La Boétie ?', 'mcq', '["Montaigne","Rabelais","Ronsard","Calvin"]'::jsonb, 0, 'Il lui consacre le chapitre « De l’amitié » des Essais.', 5),
    ('287c9abe-d344-533e-9f98-7e678bca3f52'::uuid, 'abc68a54-a5d3-5c4b-99ca-34bff4d6cbf4'::uuid, 'Le Discours a été publié du vivant de son auteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il circule manuscrit et paraît après sa mort, notamment chez les protestants.', 6),
    ('6e9bb243-5f81-5572-b0ed-c70e196c7c45'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Quel est le double sens du libertinage de Dom Juan ?', 'mcq', '["Il est libertin de mœurs et de pensée","Il est joueur et dépensier","Il est athée mais fidèle","Il est noble et pauvre"]'::jsonb, 0, 'Il ne croit « qu’au fait que deux et deux sont quatre ».', 1),
    ('5f608ddb-17bf-5124-8dd0-5eb2de954eb4'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Qui est Sganarelle ?', 'mcq', '["Le valet de Dom Juan, à la fois complice et censeur","Le père de Dom Juan","Le frère d’Elvire","Un paysan"]'::jsonb, 0, 'Il réclame ses gages dans la dernière réplique de la pièce.', 2),
    ('2f709291-d40a-5d9c-bf06-e4c9942fd66b'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Que fait Dom Juan à l’acte V ?', 'mcq', '["Il feint la conversion religieuse","Il se marie avec Elvire","Il fuit à l’étranger","Il se rend à la justice"]'::jsonb, 0, '« L’hypocrisie est un vice à la mode » : c’est la scène la plus scandaleuse.', 3),
    ('88611ba3-d728-58ed-b8b3-ffb370de661c'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Qui entraîne Dom Juan dans les flammes ?', 'mcq', '["La statue du Commandeur","Les frères d’Elvire","Le pauvre","M. Dimanche"]'::jsonb, 0, 'Il l’avait invitée à souper par bravade.', 4),
    ('bdf3a7d3-2ed7-5780-9a8d-3e702d7fcffd'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'Quelle particularité formelle la pièce présente-t-elle ?', 'mcq', '["Elle est en prose et ne respecte pas les unités","Elle est en alexandrins","Elle tient en un acte","Elle n’a pas de valet"]'::jsonb, 0, 'Multiplicité des lieux et machinerie spectaculaire.', 5),
    ('df417479-bd7a-5aa6-842a-c88c02090785'::uuid, 'b8a4b461-055b-51f8-ad58-3085c1a0c268'::uuid, 'La pièce fut jouée sans interruption après sa création.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle fut retirée après une quinzaine de représentations, sous la pression des dévots.', 6),
    ('f82e3cc7-d821-51be-b58b-541118efe538'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Qu’est-ce qui fait perdre la raison à don Quichotte ?', 'mcq', '["La lecture excessive de romans de chevalerie","Un chagrin d’amour","Une maladie","La misère"]'::jsonb, 0, 'Le roman interroge ce que lire fait à la vie.', 1),
    ('2948c8e8-9bf3-53e2-aa5b-d378a51bcd14'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Qui est Sancho Panza ?', 'mcq', '["Son écuyer, paysan pratique et proverbial","Son frère","Un chevalier rival","Le curé du village"]'::jsonb, 0, 'Le duo idéaliste/réaliste est devenu un modèle romanesque.', 2),
    ('302f2e74-53ea-576d-b7a0-6d6b0ed488d9'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Que sont, pour don Quichotte, les moulins à vent ?', 'mcq', '["Des géants à combattre","Des châteaux","Des armées ennemies","Des monstres marins"]'::jsonb, 0, 'La scène est devenue le symbole du combat magnifique et perdu.', 3),
    ('72282884-55e4-5d60-b7b3-25eb59580f56'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Quelle est la particularité de la seconde partie, publiée en 1615 ?', 'mcq', '["Les personnages ont lu la première partie et sont reconnus","Elle se déroule en France","Sancho y disparaît","Elle est écrite en vers"]'::jsonb, 0, 'Cette mise en abyme est d’une modernité stupéfiante.', 4),
    ('70d384e8-baae-518f-9038-6b71a1ff7146'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Don Quichotte recouvre la raison, puis meurt","Il devient roi","Il épouse Dulcinée","Il repart pour de nouvelles aventures"]'::jsonb, 0, 'La guérison coïncide avec la fin de la vie : c’est le sens du dénouement.', 5),
    ('e9a60e21-7a61-5afa-982a-356a9aef4d97'::uuid, 'deb19820-543e-53a1-9177-167c06edc3b3'::uuid, 'Le roman est une simple parodie sans portée réflexive.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La parodie devient une réflexion sur la fiction elle-même : c’est ce qui en fait le premier roman moderne.', 6),
    ('c0aad208-9ad0-5849-a7a5-68696d55e7d4'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Quel épisode fonde la mémoire involontaire ?', 'mcq', '["La madeleine trempée dans le thé","La visite de l’église de Combray","La promenade du côté des Guermantes","Le baiser du soir"]'::jsonb, 0, 'Un goût fait resurgir tout un pan du passé oublié.', 1),
    ('124246e9-e59c-51a1-a32f-52a6bb5943aa'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Que raconte « Un amour de Swann » ?', 'mcq', '["La passion jalouse de Swann pour Odette, avant la naissance du narrateur","L’enfance du narrateur","Le mariage de Gilberte","La guerre de 1914"]'::jsonb, 0, 'Ce récit à la troisième personne fonctionne comme un roman dans le roman.', 2),
    ('81a636ce-672d-5f4c-9dad-e0bfc7be6a57'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Quelle œuvre musicale hante Swann ?', 'mcq', '["La « petite phrase » de la sonate de Vinteuil","Une symphonie de Beethoven","Un opéra de Wagner","Une valse de Chopin"]'::jsonb, 0, 'Elle devient l’air national de son amour.', 3),
    ('11eb5a15-e1ef-5421-aca3-a9586ccd5211'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Comment le premier volume a-t-il été publié ?', 'mcq', '["À compte d’auteur, en 1913, après plusieurs refus","Chez Gallimard, immédiatement accepté","En feuilleton dans un journal","À titre posthume"]'::jsonb, 0, 'Gide, qui l’avait refusé pour la NRF, le regretta amèrement.', 4),
    ('1a7a28e5-e45f-51bd-a907-91aa30862d68'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Quels sont les « deux côtés » de Combray ?', 'mcq', '["Le côté de chez Swann et le côté des Guermantes","Le côté du parc et celui de l’église","Le côté nord et le côté sud","Le côté de la mer et celui de la ville"]'::jsonb, 0, 'Ils structurent toute la Recherche.', 5),
    ('3c9b9be1-94a4-5bef-a95a-91be3d529ddd'::uuid, '70b9be34-8b05-5ceb-99ac-d11de7544530'::uuid, 'Swann finit par épouser Odette.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors même qu’il a conclu qu’elle n’était pas son genre : c’est le paradoxe du désir proustien.', 6),
    ('84db6031-fbaf-56f5-b304-a78942fefad0'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Que veut Électre dans la pièce ?', 'mcq', '["La vérité entière, quelles qu’en soient les conséquences","Le pouvoir à Argos","Sauver sa mère","Épouser le jardinier"]'::jsonb, 0, 'Elle refuse tout compromis, même quand la ville est menacée.', 1),
    ('4797c73c-ed30-5910-8d90-569c4f308da9'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Comment Égisthe tente-t-il de neutraliser Électre ?', 'mcq', '["En la mariant au jardinier","En l’exilant","En l’emprisonnant","En la faisant taire par la force"]'::jsonb, 0, 'Un mariage médiocre l’écarterait du destin royal.', 2),
    ('d3851b41-52de-5420-9ef0-58508be7fa0b'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Sous quelle forme les Euménides apparaissent-elles ?', 'mcq', '["Trois petites filles qui grandissent d’acte en acte","Trois vieilles femmes","Des ombres invisibles","Des soldats"]'::jsonb, 0, 'Leur croissance accompagne la montée de la vengeance.', 3),
    ('e124034e-a390-50e8-845e-ada6cd08d183'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Que se passe-t-il pendant qu’Oreste accomplit la vengeance ?', 'mcq', '["Les Corinthiens attaquent et Argos brûle","Une fête est célébrée","Le peuple se révolte contre Électre","Un traité de paix est signé"]'::jsonb, 0, 'La justice absolue coûte la ville.', 4),
    ('2f2cb57f-9b1d-5262-a654-ac680f28eced'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Par quelle réplique la pièce se termine-t-elle ?', 'mcq', '["« Cela s’appelle l’aurore »","« Tout est perdu »","« La guerre n’aura pas lieu »","« Adieu, Argos »"]'::jsonb, 0, 'Une des fins les plus célèbres du théâtre français.', 5),
    ('921459c4-7a5a-5245-bf41-f4ac00c9fa41'::uuid, 'd8d2f1f2-85a4-51fa-9001-343f1e1bf7b8'::uuid, 'Égisthe est présenté comme un méchant sans nuance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pouvoir a fait de lui un vrai chef : c’est ce qui rend le dilemme réel.', 6),
    ('8046a295-3170-543f-a7db-2fd65f991f6b'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Qu’attendent Vladimir et Estragon ?', 'mcq', '["Un certain Godot, qui ne vient jamais","Un train","La fin de la guerre","Le retour de Pozzo"]'::jsonb, 0, 'Un garçon annonce chaque soir qu’il viendra demain.', 1),
    ('ff6d0fbe-1127-541e-8e0f-7a57f45d58ab'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Que se passe-t-il à l’acte II ?', 'mcq', '["Presque la même chose qu’à l’acte I, avec des dégradations","Godot arrive enfin","Les personnages quittent la scène","La pièce change de décor"]'::jsonb, 0, 'Pozzo est aveugle, Lucky muet, l’arbre a quelques feuilles.', 2),
    ('0c61396f-6cf2-5304-a40a-9c92642f22d7'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Quelle est la dernière indication scénique de la pièce ?', 'mcq', '["« Ils ne bougent pas », après avoir décidé de partir","« Ils sortent »","« Le rideau tombe sur Godot »","« Ils s’endorment »"]'::jsonb, 0, 'Le décalage entre la parole et l’action résume toute la pièce.', 3),
    ('c5d3db17-963d-5cd0-8d52-3a98db184760'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Qui sont Pozzo et Lucky ?', 'mcq', '["Un maître brutal et son esclave tenu en laisse","Deux amis de Vladimir","Deux messagers de Godot","Le père et le fils du garçon"]'::jsonb, 0, 'Lucky « pense » sur commande dans un monologue délirant.', 4),
    ('90460631-1ffc-52bb-893d-3eb4b98a3d8c'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Quel mouvement la pièce fonde-t-elle ?', 'mcq', '["Le théâtre de l’absurde","Le drame romantique","Le naturalisme","Le théâtre épique"]'::jsonb, 0, 'Créée en 1953, elle a bouleversé la scène européenne.', 5),
    ('a71a73b8-c489-5519-a70a-1b2f3b7f2d40'::uuid, '5e637a16-46d1-5e0c-ad3a-5fe4f32630d5'::uuid, 'Beckett a expliqué qui était Godot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a toujours refusé de le faire, laissant les lectures ouvertes.', 6),
    ('28b6bdc5-78b3-5733-9775-55af1a735cbc'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'Combien d’années la publication de l’Encyclopédie a-t-elle duré ?', 'mcq', '["De 1751 à 1772, soit une vingtaine d’années","Cinq ans","Cinquante ans","Deux ans"]'::jsonb, 0, 'Dix-sept volumes de texte et onze de planches.', 1),
    ('50cf8dba-d3e9-5588-9991-12ed9f0d24df'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'Quelle formule résume l’ambition de Diderot ?', 'mcq', '["« Changer la façon commune de penser »","« Éclairer le roi »","« Instruire les enfants »","« Sauver les Anciens »"]'::jsonb, 0, 'Diffuser le savoir est en soi une action politique.', 2),
    ('5ad20e3b-fd57-5184-ab95-2443e4827fa7'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'Quelle nouveauté les planches introduisent-elles ?', 'mcq', '["Elles donnent une dignité savante aux métiers manuels","Elles illustrent la Bible","Elles cartographient le monde","Elles reproduisent des tableaux"]'::jsonb, 0, 'La fabrication des épingles ou du papier y est décrite avec minutie.', 3),
    ('7e110798-5eb9-5b74-b620-3b5072116d92'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'Selon quel principe les savoirs sont-ils classés ?', 'mcq', '["Un arbre fondé sur les facultés humaines : mémoire, raison, imagination","L’ordre chronologique","La hiérarchie théologique","Le rang social des auteurs"]'::jsonb, 0, 'La théologie perd sa place de reine des savoirs.', 4),
    ('17dec96e-3f5d-5f9d-a323-8191b9dc3535'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'À quoi servent les renvois entre articles ?', 'mcq', '["À faire communiquer les savoirs, parfois ironiquement","À gagner de la place","À citer les sources","À classer alphabétiquement"]'::jsonb, 0, '« Anthropophages » renvoie à « Eucharistie ».', 5),
    ('875e998e-483f-5e9e-9dde-4a8254b9b8c1'::uuid, '8d9d9289-853b-5f7c-b450-ca875c096e6d'::uuid, 'L’entreprise s’est déroulée sans obstacle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Interdictions, révocations de privilège, travail à demi clandestin.', 6),
    ('650a1763-4489-5692-8cc8-bda74c10a92d'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Qui est Énée ?', 'mcq', '["Un prince troyen dont la descendance fondera Rome","Un roi grec","Un empereur romain","Un dieu latin"]'::jsonb, 0, 'Il fuit Troie avec son père sur les épaules et son fils par la main.', 1),
    ('13ef079b-8d6b-5b58-bd32-2cc62c96d750'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Que fait Didon quand Énée la quitte ?', 'mcq', '["Elle se suicide","Elle le poursuit en mer","Elle déclare la guerre à Troie","Elle épouse Turnus"]'::jsonb, 0, 'Son malheur explique, dans le poème, la haine future entre Rome et Carthage.', 2),
    ('3f588ca8-dc0e-574d-a87a-4c32476d094a'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Quelle vertu définit le héros virgilien ?', 'mcq', '["La pietas : le devoir envers les dieux, la patrie et la famille","La gloire personnelle","La ruse","La force physique"]'::jsonb, 0, 'C’est ce qui l’oppose aux héros homériques.', 3),
    ('62d9d177-1248-5b92-846a-f6c684c8a891'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Que voit Énée aux Enfers ?', 'mcq', '["Les âmes des futurs Romains, montrées par son père","Le châtiment de Didon","La destruction de Rome","Son propre tombeau"]'::jsonb, 0, 'Le passage justifie tout le destin romain.', 4),
    ('74e448ea-f3ba-5b1c-84e6-f8b410f5207e'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Comment le poème se termine-t-il ?', 'mcq', '["Par le duel où Énée tue Turnus","Par le mariage d’Énée","Par la fondation de Rome","Par le retour à Troie"]'::jsonb, 0, 'La fin est abrupte : le poème est resté inachevé.', 5),
    ('88ec3e16-c4a2-573e-b281-10cd239a2c98'::uuid, '827d34e1-ea91-56d1-a379-5f33bcb03aa9'::uuid, 'Virgile souhaitait la publication de son poème.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il demanda qu’on le brûlât ; Auguste s’y opposa.', 6),
    ('5a8a8f8c-2f70-5ee6-a738-e72111f5ae19'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Quelle forme l’ouvrage adopte-t-il ?', 'mcq', '["Un dialogue en six soirées","Un traité en chapitres","Une lettre ouverte","Un poème didactique"]'::jsonb, 0, 'Le dialogue rend visible le chemin de la compréhension.', 1),
    ('dd2d79fb-0dd9-5fd7-8673-d6fb0c0dc2a0'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Qui est l’interlocutrice du philosophe ?', 'mcq', '["Une marquise","Une astronome","Une religieuse","Sa nièce"]'::jsonb, 0, 'Elle représente le public mondain tenu à l’écart des savoirs.', 2),
    ('2513efc7-563c-5690-8472-c942b3d29d79'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Quel système astronomique est exposé ?', 'mcq', '["Celui de Copernic","Celui de Ptolémée","Celui d’Aristote","Celui de Newton"]'::jsonb, 0, 'La Terre tourne autour du Soleil, et sur elle-même.', 3),
    ('efb70fae-b339-5164-91a1-d40476593227'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Quelle hypothèse hardie l’ouvrage défend-il ?', 'mcq', '["La pluralité des mondes habités","La platitude de la Terre","L’immobilité du Soleil au centre exact de l’univers","La fin prochaine du monde"]'::jsonb, 0, 'Elle est présentée comme conjecture, jamais comme dogme.', 4),
    ('f9522386-b53d-5068-b826-b35f6081f83b'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'À quoi l’univers est-il comparé ?', 'mcq', '["À un opéra dont on cherche les machines","À une horloge cassée","À une bibliothèque","À un océan"]'::jsonb, 0, 'Le philosophe est celui qui regarde derrière le décor.', 5),
    ('5ea43950-8821-59b0-a0aa-a43d029a2b17'::uuid, '63a1033d-4479-5228-b4fe-41c8923f514e'::uuid, 'Le ton galant nuit à la rigueur du propos.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une stratégie de diffusion assumée, qui suppose la science partageable.', 6),
    ('dc31e9d6-e45e-5428-9015-239d4f5f1a4d'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Que signifie le mot « essai » chez Montaigne ?', 'mcq', '["Une tentative, une pesée de la pensée","Une démonstration achevée","Un discours public","Un récit de voyage"]'::jsonb, 0, '« Je ne peins pas l’être, je peins le passage. »', 1),
    ('753630d0-93e5-52bb-a48f-691b7038186c'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Quelle formule résume sa conception de l’éducation ?', 'mcq', '["« Une tête bien faite plutôt que bien pleine »","« Apprendre par cœur »","« Le savoir vaut la vertu »","« L’école forme le citoyen »"]'::jsonb, 0, 'Elle vient du chapitre « De l’institution des enfants ».', 2),
    ('0de4e4bd-929e-584c-9318-d1a472de4687'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Comment Montaigne explique-t-il son amitié avec La Boétie ?', 'mcq', '["« Parce que c’était lui, parce que c’était moi »","Par la communauté d’intérêts","Par la proximité géographique","Par une dette morale"]'::jsonb, 0, 'La formule est devenue la définition même de l’amitié.', 3),
    ('eccb643e-33dc-5ce8-88aa-d86016723f69'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Quelle est sa devise ?', 'mcq', '["« Que sais-je ? »","« Connais-toi toi-même »","« Rien de trop »","« Je pense donc je suis »"]'::jsonb, 0, 'Le doute y est une discipline, non une paresse.', 4),
    ('3e17effb-8366-5419-adda-bbc265436253'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Quel contexte historique éclaire les Essais ?', 'mcq', '["Les guerres de religion","La Fronde","La Révolution","La guerre de Cent Ans"]'::jsonb, 0, 'Il donne tout son prix à la leçon de tolérance et de mesure.', 5),
    ('306c5977-c59a-5d2c-8d7c-9257dcbcf0b1'::uuid, 'b9518301-2722-5dcc-99d6-18a034a405b1'::uuid, 'Montaigne écrit un traité systématique et ordonné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Digressions, contradictions, ajouts successifs : la forme dit la méthode.', 6),
    ('3760d75b-9bf8-5e59-b692-36007838f723'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Qui est Léopold Sédar Senghor ?', 'mcq', '["Un poète sénégalais, premier président du Sénégal et académicien français","Un romancier ivoirien","Un dramaturge camerounais","Un essayiste haïtien"]'::jsonb, 0, 'Il est le premier Africain élu à l’Académie française.', 1),
    ('46cad016-a0c9-559f-a1a6-b198cd62fe62'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Qu’est-ce que la négritude ?', 'mcq', '["La revendication assumée d’une identité et d’une culture noires","Un mouvement pictural","Une théorie économique","Un parti politique sénégalais"]'::jsonb, 0, 'Forgée avec Aimé Césaire et Léon-Gontran Damas dans les années 1930.', 2),
    ('e0493f14-9858-5411-933b-6a080a4955f0'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Quelle indication figure souvent en tête des poèmes ?', 'mcq', '["Un instrument africain d’accompagnement, comme la kôra","Une date de composition","Un lieu de rédaction","Une dédicace à un ami"]'::jsonb, 0, 'La poésie y est faite pour être dite et accompagnée, comme chez le griot.', 3),
    ('129736f8-1b44-5b27-8316-5a4c582f02f3'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Quel long poème dramatique est au cœur du recueil ?', 'mcq', '["Chaka, sur le roi zoulou","Cahier d’un retour au pays natal","Le Bateau ivre","Zone"]'::jsonb, 0, 'Cahier d’un retour au pays natal est de Césaire.', 4),
    ('f44e7296-c825-5c2c-aff4-67e9e12563f2'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'Quelle forme Senghor privilégie-t-il ?', 'mcq', '["Le verset ample, en vers libres","Le sonnet","L’alexandrin rimé","Le haïku"]'::jsonb, 0, 'Il s’inspire de Claudel et de Saint-John Perse.', 5),
    ('9cda1ce6-ad57-5e00-a1e0-bb9eb97aa63f'::uuid, '8b5a1006-0daa-5b13-b86d-798b7bfada9a'::uuid, 'La négritude de Senghor est plus révoltée que celle de Césaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : Senghor est plus lyrique et conciliateur, Césaire plus révolté.', 6)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 261 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 261 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
